insert into recipes (id, title, category, prep_time_minutes, servings, difficulty, image, ingredients, steps, key_ingredients) values
  ('arroz-branco', 'Arroz branco soltinho', 'acompanhamento', 25, 4, 'facil', NULL, '[{"id": "arroz", "name": "Arroz", "text": "2 xícaras de arroz", "optional": false}, {"id": "agua", "name": "Água", "text": "4 xícaras de água quente", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho amassados", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/4 de cebola picada", "optional": true}, {"id": "sal", "name": "Sal", "text": "1 colher (chá) de sal", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "1 colher (sopa) de óleo", "optional": false}]'::jsonb, '[{"order": 1, "text": "Refogue o alho e a cebola no óleo até perfumar.", "timerSeconds": 60}, {"order": 2, "text": "Junte o arroz e frite, mexendo, até os grãos ficarem opacos.", "timerSeconds": 120}, {"order": 3, "text": "Adicione a água quente e o sal. Cozinhe em fogo baixo com a panela semitampada até secar.", "timerSeconds": 900}, {"order": 4, "text": "Desligue e deixe descansar tampado antes de servir.", "timerSeconds": 300}]'::jsonb, ARRAY['arroz','alho']::text[]),
  ('arroz-de-brocolis', 'Arroz de brócolis', 'acompanhamento', 30, 4, 'facil', NULL, '[{"id": "arroz", "name": "Arroz", "text": "2 xícaras de arroz", "optional": false}, {"id": "brocolis", "name": "Brócolis", "text": "1 maço de brócolis picado", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/4 de cebola", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue o alho e a cebola, junte o arroz e frite levemente.", "timerSeconds": 120}, {"order": 2, "text": "Cubra com 4 xícaras de água quente e sal e cozinhe.", "timerSeconds": 600}, {"order": 3, "text": "Quando a água estiver quase secando, junte o brócolis por cima e tampe.", "timerSeconds": 360}, {"order": 4, "text": "Misture e deixe descansar tampado.", "timerSeconds": 300}]'::jsonb, ARRAY['arroz','brocolis','alho']::text[]),
  ('batata-rustica', 'Batata rústica assada', 'acompanhamento', 50, 4, 'facil', NULL, '[{"id": "batata", "name": "Batata", "text": "6 batatas com casca em gomos", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "4 colheres (sopa) de azeite", "optional": false}, {"id": "alho", "name": "Alho", "text": "4 dentes de alho com casca", "optional": false}, {"id": "paprica", "name": "Páprica", "text": "1 colher (chá) de páprica", "optional": true}, {"id": "oregano", "name": "Orégano", "text": "Alecrim ou orégano", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe as batatas em água com sal só até começarem a amolecer.", "timerSeconds": 420}, {"order": 2, "text": "Escorra, espalhe numa assadeira e tempere com azeite, sal, páprica, orégano e os dentes de alho."}, {"order": 3, "text": "Asse a 220 °C, virando na metade, até dourarem e ficarem crocantes.", "timerSeconds": 2100}]'::jsonb, ARRAY['batata','azeite','alho']::text[]),
  ('chuchu-refogado', 'Chuchu refogado', 'acompanhamento', 20, 4, 'facil', NULL, '[{"id": "chuchu", "name": "Chuchu", "text": "3 chuchus em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola e o alho num fio de óleo.", "timerSeconds": 120}, {"order": 2, "text": "Junte o chuchu e o tomate, tempere com sal e tampe. O chuchu cozinha na própria água.", "timerSeconds": 720}, {"order": 3, "text": "Finalize com cheiro-verde."}]'::jsonb, ARRAY['chuchu','cebola','alho']::text[]),
  ('couve-refogada', 'Couve refogada', 'acompanhamento', 10, 4, 'facil', NULL, '[{"id": "couve", "name": "Couve", "text": "1 maço de couve cortada fininha", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "50 g de bacon", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure o alho (e o bacon, se usar) num fio de óleo.", "timerSeconds": 120}, {"order": 2, "text": "Junte a couve e salteie em fogo alto só até murchar e ficar verde-brilhante.", "timerSeconds": 120}, {"order": 3, "text": "Tempere com sal e sirva na hora."}]'::jsonb, ARRAY['couve','alho']::text[]),
  ('couve-flor-gratinada', 'Couve-flor gratinada', 'acompanhamento', 40, 4, 'facil', NULL, '[{"id": "couve-flor", "name": "Couve-flor", "text": "1 couve-flor em buquês", "optional": false}, {"id": "leite", "name": "Leite", "text": "2 xícaras de leite", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "2 colheres (sopa) de manteiga", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "2 colheres (sopa) de farinha de trigo", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "1 xícara de muçarela ralada", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe a couve-flor em água com sal até ficar macia, mas firme.", "timerSeconds": 420}, {"order": 2, "text": "Faça um molho branco: derreta a manteiga, junte a farinha e depois o leite aos poucos, mexendo até engrossar.", "timerSeconds": 360}, {"order": 3, "text": "Coloque a couve-flor num refratário, cubra com o molho, a muçarela e o parmesão."}, {"order": 4, "text": "Gratine a 200 °C.", "timerSeconds": 900}]'::jsonb, ARRAY['couve-flor','leite','manteiga','farinha-trigo','queijo']::text[]),
  ('creme-de-milho', 'Creme de milho', 'acompanhamento', 15, 4, 'facil', NULL, '[{"id": "milho", "name": "Milho verde em lata", "text": "2 latas de milho escorrido", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 1/2 xícara de leite", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola picada", "optional": false}, {"id": "amido-milho", "name": "Amido de milho", "text": "1 colher (sopa) de amido de milho", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "Muçarela ou parmesão para gratinar", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata 1 lata e meia de milho com o leite e o amido no liquidificador."}, {"order": 2, "text": "Refogue a cebola na manteiga, junte a mistura batida e o resto do milho inteiro."}, {"order": 3, "text": "Cozinhe mexendo em fogo baixo até engrossar.", "timerSeconds": 360}, {"order": 4, "text": "Sirva assim ou cubra com queijo e gratine no forno.", "timerSeconds": 600}]'::jsonb, ARRAY['milho','leite','manteiga','cebola','amido-milho']::text[]),
  ('farofa-de-bacon', 'Farofa de bacon', 'acompanhamento', 15, 6, 'facil', NULL, '[{"id": "farinha-mandioca", "name": "Farinha de mandioca", "text": "2 xícaras de farinha de mandioca", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "150 g de bacon em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "2 colheres (sopa) de manteiga", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure o bacon até ficar crocante.", "timerSeconds": 360}, {"order": 2, "text": "Junte a manteiga e a cebola e refogue. Se usar, mexa os ovos junto.", "timerSeconds": 180}, {"order": 3, "text": "Adicione a farinha aos poucos, mexendo, até ficar dourada e soltinha.", "timerSeconds": 240}, {"order": 4, "text": "Acerte o sal e finalize com cheiro-verde."}]'::jsonb, ARRAY['farinha-mandioca','bacon','cebola','manteiga']::text[]),
  ('feijao-caseiro', 'Feijão caseiro', 'acompanhamento', 60, 6, 'facil', NULL, '[{"id": "feijao", "name": "Feijão", "text": "2 xícaras de feijão carioca", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola picada", "optional": false}, {"id": "louro", "name": "Folha de louro", "text": "2 folhas de louro", "optional": true}, {"id": "bacon", "name": "Bacon", "text": "50 g de bacon", "optional": true}]'::jsonb, '[{"order": 1, "text": "Escolha e lave o feijão. Se der, deixe de molho por algumas horas.", "timerSeconds": 3600}, {"order": 2, "text": "Cozinhe na pressão com o louro e água cobrindo dois dedos acima.", "timerSeconds": 1500}, {"order": 3, "text": "Doure o bacon, o alho e a cebola numa frigideira."}, {"order": 4, "text": "Junte uma concha do feijão ao refogado, amasse e volte tudo para a panela. Cozinhe destampado até engrossar.", "timerSeconds": 600}]'::jsonb, ARRAY['feijao','alho','cebola']::text[]),
  ('mandioca-frita', 'Mandioca frita', 'acompanhamento', 45, 4, 'facil', NULL, '[{"id": "mandioca", "name": "Mandioca", "text": "1 kg de mandioca", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}, {"id": "sal", "name": "Sal", "text": "Sal a gosto", "optional": false}]'::jsonb, '[{"order": 1, "text": "Cozinhe a mandioca em água com sal até ficar macia, mas sem desmanchar.", "timerSeconds": 1200}, {"order": 2, "text": "Escorra, corte em palitos grossos e deixe esfriar para não espirrar.", "timerSeconds": 600}, {"order": 3, "text": "Frite em óleo bem quente até dourar.", "timerSeconds": 360}, {"order": 4, "text": "Escorra em papel-toalha e salpique sal."}]'::jsonb, ARRAY['mandioca']::text[]),
  ('pure-de-batata', 'Purê de batata', 'acompanhamento', 35, 4, 'facil', NULL, '[{"id": "batata", "name": "Batata", "text": "1 kg de batata", "optional": false}, {"id": "leite", "name": "Leite", "text": "3/4 de xícara de leite quente", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "2 colheres (sopa) de manteiga", "optional": false}, {"id": "noz-moscada", "name": "Noz-moscada", "text": "1 pitada de noz-moscada", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe as batatas descascadas em água com sal até ficarem bem macias.", "timerSeconds": 1200}, {"order": 2, "text": "Escorra e amasse ainda quentes com um espremedor."}, {"order": 3, "text": "Leve ao fogo baixo com a manteiga e o leite, mexendo até ficar cremoso.", "timerSeconds": 180}, {"order": 4, "text": "Acerte o sal e a noz-moscada."}]'::jsonb, ARRAY['batata','leite','manteiga']::text[]),
  ('tutu-de-feijao', 'Tutu de feijão', 'acompanhamento', 30, 4, 'facil', NULL, '[{"id": "feijao", "name": "Feijão", "text": "3 xícaras de feijão cozido com caldo", "optional": false}, {"id": "farinha-mandioca", "name": "Farinha de mandioca", "text": "1/2 xícara de farinha de mandioca", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "100 g de bacon", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata o feijão com o caldo no liquidificador."}, {"order": 2, "text": "Doure o bacon, junte a cebola e o alho.", "timerSeconds": 360}, {"order": 3, "text": "Adicione o feijão batido e, quando ferver, vá juntando a farinha aos poucos, mexendo até engrossar.", "timerSeconds": 300}, {"order": 4, "text": "Finalize com cheiro-verde."}]'::jsonb, ARRAY['feijao','farinha-mandioca','bacon','cebola','alho']::text[]),
  ('vagem-com-cenoura', 'Vagem com cenoura na manteiga', 'acompanhamento', 20, 4, 'facil', NULL, '[{"id": "vagem", "name": "Vagem", "text": "300 g de vagem em pedaços", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "2 cenouras em palitos", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}, {"id": "alho", "name": "Alho", "text": "1 dente de alho", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe a vagem e a cenoura em água fervente com sal até ficarem macias, mas ainda crocantes.", "timerSeconds": 360}, {"order": 2, "text": "Escorra e passe na água fria para manter a cor."}, {"order": 3, "text": "Salteie na manteiga com o alho e acerte o sal.", "timerSeconds": 120}]'::jsonb, ARRAY['vagem','cenoura','manteiga']::text[]),
  ('cafe-gelado', 'Café gelado cremoso', 'bebida', 5, 2, 'facil', NULL, '[{"id": "cafe", "name": "Café em pó", "text": "1 xícara de café forte frio", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 xícara de leite gelado", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "3 colheres (sopa) de leite condensado", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "1 colher (sopa) de chocolate em pó", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata tudo no liquidificador com alguns cubos de gelo até espumar.", "timerSeconds": 30}, {"order": 2, "text": "Sirva em copos altos com mais gelo."}]'::jsonb, ARRAY['cafe','leite','leite-condensado']::text[]),
  ('chocolate-quente', 'Chocolate quente cremoso', 'bebida', 10, 2, 'facil', NULL, '[{"id": "leite", "name": "Leite", "text": "2 xícaras de leite", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "3 colheres (sopa) de chocolate em pó", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "2 colheres (sopa) de açúcar", "optional": false}, {"id": "amido-milho", "name": "Amido de milho", "text": "1 colher (sopa) de amido de milho", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela", "optional": true}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "2 colheres (sopa) de creme de leite", "optional": true}]'::jsonb, '[{"order": 1, "text": "Dissolva o amido em um pouco de leite frio."}, {"order": 2, "text": "Leve o resto do leite ao fogo com o chocolate, o açúcar e o amido dissolvido, mexendo sempre até engrossar.", "timerSeconds": 300}, {"order": 3, "text": "Desligue, misture o creme de leite e sirva com canela."}]'::jsonb, ARRAY['leite','chocolate-po','amido-milho']::text[]),
  ('limonada', 'Limonada suíça', 'bebida', 10, 4, 'facil', NULL, '[{"id": "limao", "name": "Limão", "text": "3 limões taiti", "optional": false}, {"id": "agua", "name": "Água", "text": "1 litro de água gelada", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "6 colheres (sopa) de açúcar", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1/2 lata de leite condensado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Lave bem os limões, corte as pontas e corte em 4."}, {"order": 2, "text": "Bata no liquidificador com a água e o açúcar por poucos segundos, para não amargar.", "timerSeconds": 15}, {"order": 3, "text": "Coe, junte o leite condensado se quiser e sirva com gelo."}]'::jsonb, ARRAY['limao']::text[]),
  ('suco-laranja-cenoura', 'Suco de laranja com cenoura', 'bebida', 10, 2, 'facil', NULL, '[{"id": "laranja", "name": "Laranja", "text": "4 laranjas", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura pequena", "optional": false}, {"id": "gengibre", "name": "Gengibre", "text": "1 rodela de gengibre", "optional": true}]'::jsonb, '[{"order": 1, "text": "Esprema as laranjas."}, {"order": 2, "text": "Bata o suco com a cenoura picada e o gengibre no liquidificador."}, {"order": 3, "text": "Coe se preferir e sirva gelado."}]'::jsonb, ARRAY['laranja','cenoura']::text[]),
  ('vitamina-de-banana', 'Vitamina de banana', 'bebida', 5, 2, 'facil', NULL, '[{"id": "banana", "name": "Banana", "text": "2 bananas", "optional": false}, {"id": "leite", "name": "Leite", "text": "2 xícaras de leite gelado", "optional": false}, {"id": "aveia", "name": "Aveia", "text": "2 colheres (sopa) de aveia", "optional": true}, {"id": "mel", "name": "Mel", "text": "1 colher (sopa) de mel", "optional": true}]'::jsonb, '[{"order": 1, "text": "Descasque as bananas e corte em pedaços."}, {"order": 2, "text": "Bata tudo no liquidificador até ficar cremoso."}, {"order": 3, "text": "Sirva na hora para não escurecer."}]'::jsonb, ARRAY['banana','leite']::text[]),
  ('vitamina-de-mamao', 'Vitamina de mamão com laranja', 'bebida', 5, 2, 'facil', NULL, '[{"id": "mamao", "name": "Mamão", "text": "1/2 mamão papaia", "optional": false}, {"id": "laranja", "name": "Laranja", "text": "Suco de 2 laranjas", "optional": false}, {"id": "iogurte", "name": "Iogurte natural", "text": "1 pote de iogurte natural", "optional": true}, {"id": "mel", "name": "Mel", "text": "1 colher (sopa) de mel", "optional": true}]'::jsonb, '[{"order": 1, "text": "Retire as sementes do mamão e pegue a polpa com uma colher."}, {"order": 2, "text": "Bata tudo no liquidificador com gelo até ficar cremoso.", "timerSeconds": 30}, {"order": 3, "text": "Sirva na hora."}]'::jsonb, ARRAY['mamao','laranja']::text[]),
  ('parfait-de-iogurte', 'Copo de iogurte com frutas e aveia', 'cafe-da-manha', 5, 1, 'facil', NULL, '[{"id": "iogurte", "name": "Iogurte natural", "text": "1 pote de iogurte natural", "optional": false}, {"id": "aveia", "name": "Aveia", "text": "2 colheres (sopa) de aveia", "optional": false}, {"id": "banana", "name": "Banana", "text": "1/2 banana em rodelas", "optional": false}, {"id": "morango", "name": "Morango", "text": "Morangos picados", "optional": true}, {"id": "mel", "name": "Mel", "text": "1 colher (sopa) de mel", "optional": true}]'::jsonb, '[{"order": 1, "text": "Num copo, faça uma camada de iogurte, uma de aveia e uma de frutas."}, {"order": 2, "text": "Repita as camadas e finalize com mel."}]'::jsonb, ARRAY['iogurte','aveia','banana']::text[]),
  ('crepioca', 'Crepioca', 'cafe-da-manha', 10, 1, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "1 ovo", "optional": false}, {"id": "goma-tapioca", "name": "Goma de tapioca", "text": "2 colheres (sopa) de goma de tapioca", "optional": false}, {"id": "sal", "name": "Sal", "text": "1 pitada de sal", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "Queijo para rechear", "optional": true}, {"id": "tomate", "name": "Tomate", "text": "Tomate picado para rechear", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata o ovo com a goma de tapioca e o sal até ficar homogêneo."}, {"order": 2, "text": "Despeje numa frigideira antiaderente untada, espalhando bem. Cozinhe em fogo baixo.", "timerSeconds": 120}, {"order": 3, "text": "Vire, recheie com queijo e tomate e dobre ao meio.", "timerSeconds": 60}]'::jsonb, ARRAY['ovo','goma-tapioca']::text[]),
  ('cuscuz-nordestino-com-ovo', 'Cuscuz nordestino com ovo', 'cafe-da-manha', 20, 2, 'facil', NULL, '[{"id": "flocao", "name": "Flocão de milho", "text": "2 xícaras de flocão de milho", "optional": false}, {"id": "agua", "name": "Água", "text": "1 xícara de água", "optional": false}, {"id": "sal", "name": "Sal", "text": "1 colher (chá) de sal", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o flocão com o sal e vá molhando com a água aos poucos até ficar úmido, mas soltinho."}, {"order": 2, "text": "Deixe hidratar.", "timerSeconds": 600}, {"order": 3, "text": "Coloque água na parte de baixo da cuscuzeira, a massa em cima sem apertar e tampe. Cozinhe em fogo médio.", "timerSeconds": 600}, {"order": 4, "text": "Enquanto isso, frite os ovos. Sirva o cuscuz com manteiga e os ovos por cima."}]'::jsonb, ARRAY['flocao','ovo']::text[]),
  ('mingau-de-aveia', 'Mingau de aveia', 'cafe-da-manha', 10, 1, 'facil', NULL, '[{"id": "aveia", "name": "Aveia", "text": "3 colheres (sopa) de aveia", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 xícara de leite", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1 colher (sopa) de açúcar ou mel", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela a gosto", "optional": true}, {"id": "banana", "name": "Banana", "text": "1 banana em rodelas", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o leite, a aveia e o açúcar numa panela pequena."}, {"order": 2, "text": "Cozinhe em fogo baixo, mexendo sempre, até engrossar.", "timerSeconds": 300}, {"order": 3, "text": "Sirva com canela e banana por cima."}]'::jsonb, ARRAY['aveia','leite']::text[]),
  ('omelete-de-queijo', 'Omelete de queijo', 'cafe-da-manha', 10, 1, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "2 fatias de muçarela picadas", "optional": false}, {"id": "sal", "name": "Sal", "text": "1 pitada de sal", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "1 fio de óleo", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde a gosto", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata os ovos com o sal num prato fundo até ficarem bem misturados."}, {"order": 2, "text": "Aqueça o óleo numa frigideira antiaderente em fogo médio-baixo e despeje os ovos."}, {"order": 3, "text": "Deixe cozinhar sem mexer até as bordas firmarem.", "timerSeconds": 120}, {"order": 4, "text": "Espalhe o queijo e o cheiro-verde sobre metade da omelete, dobre ao meio e deixe o queijo derreter.", "timerSeconds": 60}]'::jsonb, ARRAY['ovo','queijo']::text[]),
  ('ovos-cozidos', 'Ovos cozidos no ponto', 'cafe-da-manha', 15, 2, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "4 ovos", "optional": false}, {"id": "agua", "name": "Água", "text": "Água suficiente para cobrir", "optional": false}, {"id": "sal", "name": "Sal", "text": "Sal a gosto", "optional": false}]'::jsonb, '[{"order": 1, "text": "Coloque a água para ferver numa panela."}, {"order": 2, "text": "Com a água fervendo, abaixe os ovos com uma colher. Para gema mole, conte 6 minutos; para gema dura, 10 minutos.", "timerSeconds": 600}, {"order": 3, "text": "Passe os ovos para uma tigela com água fria para parar o cozimento.", "timerSeconds": 120}, {"order": 4, "text": "Descasque e sirva com sal."}]'::jsonb, ARRAY['ovo']::text[]),
  ('ovos-mexidos-cremosos', 'Ovos mexidos cremosos', 'cafe-da-manha', 8, 1, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (chá) de manteiga", "optional": false}, {"id": "requeijao", "name": "Requeijão", "text": "1 colher (sopa) de requeijão", "optional": true}, {"id": "sal", "name": "Sal", "text": "Sal a gosto", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata levemente os ovos com uma pitada de sal."}, {"order": 2, "text": "Derreta a manteiga em fogo baixo e junte os ovos."}, {"order": 3, "text": "Mexa devagar com uma espátula, puxando dos lados para o centro, até quase firmar.", "timerSeconds": 180}, {"order": 4, "text": "Desligue o fogo, misture o requeijão e sirva na hora, ainda cremoso."}]'::jsonb, ARRAY['ovo','manteiga']::text[]),
  ('panqueca-de-banana-e-aveia', 'Panqueca de banana e aveia', 'cafe-da-manha', 15, 1, 'facil', NULL, '[{"id": "banana", "name": "Banana", "text": "1 banana madura", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "1 ovo", "optional": false}, {"id": "aveia", "name": "Aveia", "text": "3 colheres (sopa) de aveia", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela a gosto", "optional": true}, {"id": "mel", "name": "Mel", "text": "Mel para servir", "optional": true}]'::jsonb, '[{"order": 1, "text": "Amasse bem a banana com um garfo."}, {"order": 2, "text": "Misture o ovo, a aveia e a canela até virar uma massa grossa."}, {"order": 3, "text": "Unte levemente uma frigideira e despeje pequenas porções da massa. Doure em fogo baixo.", "timerSeconds": 120}, {"order": 4, "text": "Vire e doure o outro lado. Sirva com mel.", "timerSeconds": 90}]'::jsonb, ARRAY['banana','ovo','aveia']::text[]),
  ('tapioca-de-queijo-e-presunto', 'Tapioca de queijo e presunto', 'cafe-da-manha', 10, 1, 'facil', NULL, '[{"id": "goma-tapioca", "name": "Goma de tapioca", "text": "4 colheres (sopa) de goma de tapioca", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "2 fatias de muçarela", "optional": false}, {"id": "presunto", "name": "Presunto", "text": "2 fatias de presunto", "optional": false}]'::jsonb, '[{"order": 1, "text": "Passe a goma por uma peneira direto na frigideira fria, formando um disco uniforme."}, {"order": 2, "text": "Leve ao fogo médio até a goma grudar e formar uma massa única.", "timerSeconds": 90}, {"order": 3, "text": "Vire a tapioca, coloque o queijo e o presunto em metade e dobre."}, {"order": 4, "text": "Deixe mais um pouco até o queijo derreter.", "timerSeconds": 60}]'::jsonb, ARRAY['goma-tapioca','queijo','presunto']::text[]),
  ('torrada-de-abacate', 'Torrada de abacate', 'cafe-da-manha', 10, 2, 'facil', NULL, '[{"id": "abacate", "name": "Abacate", "text": "1/2 abacate maduro", "optional": false}, {"id": "pao", "name": "Pão francês", "text": "2 pães franceses ou 2 fatias de pão de forma", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1/2 limão", "optional": false}, {"id": "sal", "name": "Sal", "text": "Sal e pimenta a gosto", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": true}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Toste o pão na frigideira ou na torradeira.", "timerSeconds": 180}, {"order": 2, "text": "Amasse o abacate com o limão, o sal e a pimenta."}, {"order": 3, "text": "Espalhe sobre as torradas e finalize com tomate ou um ovo frito."}]'::jsonb, ARRAY['abacate','pao','limao']::text[]),
  ('bolinho-de-arroz', 'Bolinho de arroz', 'lanche', 30, 4, 'facil', NULL, '[{"id": "arroz", "name": "Arroz", "text": "2 xícaras de arroz cozido (pode ser de ontem)", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "1 ovo", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "4 colheres (sopa) de farinha de trigo", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "1/2 xícara de muçarela ou parmesão ralado", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde picado", "optional": true}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture o arroz, o ovo, o queijo, o cheiro-verde e a farinha até dar liga. Acerte o sal."}, {"order": 2, "text": "Aqueça o óleo e pingue colheradas da massa."}, {"order": 3, "text": "Frite até dourar, virando na metade.", "timerSeconds": 240}, {"order": 4, "text": "Escorra em papel-toalha e sirva quente."}]'::jsonb, ARRAY['arroz','ovo','farinha-trigo','queijo']::text[]),
  ('bolinho-de-chuva', 'Bolinho de chuva', 'lanche', 30, 4, 'facil', NULL, '[{"id": "farinha-trigo", "name": "Farinha de trigo", "text": "2 xícaras de farinha de trigo", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": false}, {"id": "leite", "name": "Leite", "text": "3/4 de xícara de leite", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1/2 xícara de açúcar, mais um pouco para empanar", "optional": false}, {"id": "fermento", "name": "Fermento químico", "text": "1 colher (sopa) de fermento químico", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela para empanar", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture os ovos, o açúcar e o leite. Junte a farinha aos poucos e, por último, o fermento."}, {"order": 2, "text": "Aqueça o óleo em fogo médio. Com duas colheres, pingue porções da massa."}, {"order": 3, "text": "Frite até dourar por igual, virando na metade.", "timerSeconds": 240}, {"order": 4, "text": "Escorra em papel-toalha e passe na mistura de açúcar com canela."}]'::jsonb, ARRAY['farinha-trigo','ovo','leite','fermento','canela']::text[]),
  ('cachorro-quente', 'Cachorro-quente', 'lanche', 25, 4, 'facil', NULL, '[{"id": "salsicha", "name": "Salsicha", "text": "8 salsichas", "optional": false}, {"id": "pao", "name": "Pão francês", "text": "8 pães de cachorro-quente ou franceses", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "1 sachê de molho de tomate", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": true}, {"id": "batata-palha", "name": "Batata palha", "text": "Batata palha", "optional": true}, {"id": "milho", "name": "Milho verde em lata", "text": "Milho", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola num fio de óleo até murchar.", "timerSeconds": 180}, {"order": 2, "text": "Junte as salsichas cortadas, o tomate e o molho. Cozinhe em fogo baixo.", "timerSeconds": 600}, {"order": 3, "text": "Abra os pães, recheie com as salsichas e o molho e finalize com milho e batata palha."}]'::jsonb, ARRAY['salsicha','pao','molho-tomate','cebola']::text[]),
  ('coxinha-de-frango', 'Coxinha de frango', 'lanche', 90, 6, 'dificil', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de peito de frango", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "2 xícaras de farinha de trigo", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}, {"id": "requeijao", "name": "Requeijão", "text": "3 colheres (sopa) de requeijão", "optional": true}, {"id": "ovo", "name": "Ovo", "text": "2 ovos batidos para empanar", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1 xícara de farinha de rosca", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Cozinhe o frango em 2 xícaras de água com sal. Guarde o caldo.", "timerSeconds": 1500}, {"order": 2, "text": "Desfie o frango e refogue com a cebola e o alho. Misture o requeijão e reserve."}, {"order": 3, "text": "Ferva 2 xícaras do caldo com a manteiga, despeje a farinha de uma vez e mexa até a massa soltar da panela.", "timerSeconds": 180}, {"order": 4, "text": "Espere a massa amornar e sove até ficar lisa.", "timerSeconds": 600}, {"order": 5, "text": "Abra porções na mão, recheie, feche no formato de coxinha. Passe no ovo e na farinha de rosca."}, {"order": 6, "text": "Frite em óleo quente até dourar.", "timerSeconds": 240}]'::jsonb, ARRAY['frango','cebola','alho','farinha-trigo','manteiga','ovo','farinha-rosca']::text[]),
  ('hamburguer-caseiro', 'Hambúrguer caseiro', 'lanche', 30, 4, 'facil', NULL, '[{"id": "carne-moida", "name": "Carne moída", "text": "600 g de carne moída (acém ou patinho)", "optional": false}, {"id": "pao", "name": "Pão francês", "text": "4 pães de hambúrguer ou franceses", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "4 fatias de muçarela", "optional": false}, {"id": "alface", "name": "Alface", "text": "Alface", "optional": true}, {"id": "tomate", "name": "Tomate", "text": "1 tomate em rodelas", "optional": true}, {"id": "cebola", "name": "Cebola", "text": "1 cebola em rodelas", "optional": true}, {"id": "maionese", "name": "Maionese", "text": "Maionese ou ketchup", "optional": true}]'::jsonb, '[{"order": 1, "text": "Divida a carne em 4 bolas e achate em discos de 1,5 cm, sem amassar demais. Tempere só por fora com sal e pimenta."}, {"order": 2, "text": "Grelhe em frigideira bem quente sem mexer.", "timerSeconds": 180}, {"order": 3, "text": "Vire, coloque o queijo por cima e tampe até derreter.", "timerSeconds": 180}, {"order": 4, "text": "Toste os pães e monte com alface, tomate, cebola e molho."}]'::jsonb, ARRAY['carne-moida','pao','queijo']::text[]),
  ('misto-quente', 'Misto-quente', 'lanche', 8, 1, 'facil', NULL, '[{"id": "pao-de-forma", "name": "Pão de forma", "text": "2 fatias de pão de forma", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "2 fatias de muçarela", "optional": false}, {"id": "presunto", "name": "Presunto", "text": "2 fatias de presunto", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "Manteiga para passar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Passe manteiga no lado de fora das fatias de pão."}, {"order": 2, "text": "Monte o sanduíche com o queijo e o presunto no meio."}, {"order": 3, "text": "Doure numa frigideira em fogo baixo, apertando com a espátula.", "timerSeconds": 150}, {"order": 4, "text": "Vire e doure o outro lado até o queijo derreter.", "timerSeconds": 120}]'::jsonb, ARRAY['pao-de-forma','queijo','presunto','manteiga']::text[]),
  ('nuggets-caseiros', 'Nuggets caseiros', 'lanche', 40, 4, 'media', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de peito de frango", "optional": false}, {"id": "alho", "name": "Alho", "text": "1 dente de alho", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos batidos", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1/2 xícara de farinha de trigo", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1 xícara de farinha de rosca", "optional": false}, {"id": "paprica", "name": "Páprica", "text": "1 colher (chá) de páprica", "optional": true}]'::jsonb, '[{"order": 1, "text": "Triture o frango com o alho, a cebola, a páprica e sal no processador até virar uma pasta."}, {"order": 2, "text": "Modele os nuggets com as mãos úmidas. Passe na farinha de trigo, no ovo e na farinha de rosca."}, {"order": 3, "text": "Leve ao congelador para firmar.", "timerSeconds": 900}, {"order": 4, "text": "Asse a 200 °C virando na metade, ou frite em óleo quente até dourar.", "timerSeconds": 1200}]'::jsonb, ARRAY['frango','alho','cebola','ovo','farinha-trigo','farinha-rosca']::text[]),
  ('pipoca-de-panela', 'Pipoca de panela', 'lanche', 8, 3, 'facil', NULL, '[{"id": "milho-pipoca", "name": "Milho de pipoca", "text": "1/2 xícara de milho de pipoca", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "3 colheres (sopa) de óleo", "optional": false}, {"id": "sal", "name": "Sal", "text": "Sal a gosto", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga derretida", "optional": true}]'::jsonb, '[{"order": 1, "text": "Coloque o óleo e 3 grãos de milho na panela tampada em fogo médio-alto."}, {"order": 2, "text": "Quando os 3 grãos estourarem, junte o resto do milho e tampe."}, {"order": 3, "text": "Chacoalhe a panela de vez em quando até os estouros ficarem espaçados.", "timerSeconds": 180}, {"order": 4, "text": "Desligue, tempere com sal e manteiga derretida."}]'::jsonb, ARRAY['milho-pipoca']::text[]),
  ('pao-de-alho', 'Pão de alho caseiro', 'lanche', 15, 4, 'facil', NULL, '[{"id": "pao", "name": "Pão francês", "text": "4 pães franceses", "optional": false}, {"id": "alho", "name": "Alho", "text": "4 dentes de alho amassados", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "3 colheres (sopa) de manteiga", "optional": false}, {"id": "maionese", "name": "Maionese", "text": "1 colher (sopa) de maionese", "optional": true}, {"id": "queijo", "name": "Queijo muçarela", "text": "Muçarela ralada", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde picado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture a manteiga, o alho, a maionese e o cheiro-verde até virar uma pasta."}, {"order": 2, "text": "Faça cortes nos pães sem separar as fatias e recheie com a pasta. Cubra com queijo."}, {"order": 3, "text": "Asse em forno preaquecido a 200 °C até dourar.", "timerSeconds": 600}]'::jsonb, ARRAY['pao','alho','manteiga']::text[]),
  ('pao-de-queijo', 'Pão de queijo', 'lanche', 50, 6, 'media', NULL, '[{"id": "polvilho", "name": "Polvilho", "text": "2 xícaras de polvilho azedo", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 xícara de leite", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "1/2 xícara de óleo", "optional": false}, {"id": "sal", "name": "Sal", "text": "1 colher (chá) de sal", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": false}, {"id": "queijo-minas", "name": "Queijo minas", "text": "1 1/2 xícara de queijo minas meia cura ralado", "optional": false}]'::jsonb, '[{"order": 1, "text": "Ferva o leite com o óleo e o sal e escalde o polvilho, mexendo até formar uma massa grudenta."}, {"order": 2, "text": "Espere amornar.", "timerSeconds": 600}, {"order": 3, "text": "Junte os ovos um a um e o queijo, sovando até a massa ficar lisa."}, {"order": 4, "text": "Com as mãos untadas, faça bolinhas e coloque numa assadeira, com espaço entre elas."}, {"order": 5, "text": "Asse em forno preaquecido a 200 °C até dourar.", "timerSeconds": 1500}]'::jsonb, ARRAY['polvilho','leite','ovo','queijo-minas']::text[]),
  ('sanduiche-de-atum', 'Sanduíche de atum', 'lanche', 10, 2, 'facil', NULL, '[{"id": "atum", "name": "Atum em lata", "text": "1 lata de atum escorrido", "optional": false}, {"id": "maionese", "name": "Maionese", "text": "2 colheres (sopa) de maionese", "optional": false}, {"id": "pao-de-forma", "name": "Pão de forma", "text": "4 fatias de pão de forma", "optional": false}, {"id": "alface", "name": "Alface", "text": "Folhas de alface", "optional": true}, {"id": "tomate", "name": "Tomate", "text": "1 tomate em rodelas", "optional": true}, {"id": "milho", "name": "Milho verde em lata", "text": "2 colheres (sopa) de milho", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o atum com a maionese e o milho. Acerte o sal."}, {"order": 2, "text": "Espalhe a pasta em duas fatias de pão."}, {"order": 3, "text": "Cubra com alface, tomate e as outras fatias. Corte na diagonal."}]'::jsonb, ARRAY['atum','maionese','pao-de-forma']::text[]),
  ('sanduiche-natural-de-frango', 'Sanduíche natural de frango', 'lanche', 15, 2, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "1 xícara de frango cozido e desfiado", "optional": false}, {"id": "requeijao", "name": "Requeijão", "text": "2 colheres (sopa) de requeijão", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura ralada", "optional": false}, {"id": "pao-de-forma", "name": "Pão de forma", "text": "4 fatias de pão de forma", "optional": false}, {"id": "alface", "name": "Alface", "text": "Folhas de alface", "optional": true}, {"id": "milho", "name": "Milho verde em lata", "text": "2 colheres (sopa) de milho", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o frango com o requeijão, a cenoura e o milho. Acerte o sal."}, {"order": 2, "text": "Recheie as fatias de pão com a pasta e a alface."}, {"order": 3, "text": "Corte ao meio e sirva, ou embrulhe em plástico e guarde na geladeira."}]'::jsonb, ARRAY['frango','requeijao','cenoura','pao-de-forma']::text[]),
  ('abobrinha-recheada', 'Abobrinha recheada', 'prato-principal', 45, 2, 'facil', NULL, '[{"id": "abobrinha", "name": "Abobrinha", "text": "2 abobrinhas", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola picada", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "1 xícara de muçarela ralada", "optional": false}, {"id": "carne-moida", "name": "Carne moída", "text": "200 g de carne moída", "optional": true}, {"id": "oregano", "name": "Orégano", "text": "Orégano", "optional": true}]'::jsonb, '[{"order": 1, "text": "Corte as abobrinhas ao meio no comprido e retire o miolo com uma colher. Pique o miolo."}, {"order": 2, "text": "Refogue a cebola, o miolo picado, o tomate e a carne, se usar. Tempere.", "timerSeconds": 480}, {"order": 3, "text": "Recheie as abobrinhas, cubra com queijo e orégano."}, {"order": 4, "text": "Asse a 200 °C até a abobrinha amaciar e o queijo dourar.", "timerSeconds": 1500}]'::jsonb, ARRAY['abobrinha','tomate','cebola','queijo']::text[]),
  ('almondegas-ao-sugo', 'Almôndegas ao sugo', 'prato-principal', 45, 4, 'media', NULL, '[{"id": "carne-moida", "name": "Carne moída", "text": "500 g de carne moída", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "1 ovo", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1/2 xícara de farinha de rosca", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola ralada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "3 xícaras de molho de tomate", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão para servir", "optional": true}, {"id": "manjericao", "name": "Manjericão", "text": "Manjericão", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture a carne, o ovo, a farinha de rosca, metade da cebola, o alho e sal. Faça bolinhas."}, {"order": 2, "text": "Doure as almôndegas numa frigideira com óleo, virando para dourar por igual.", "timerSeconds": 480}, {"order": 3, "text": "Em uma panela, refogue o resto da cebola e junte o molho de tomate."}, {"order": 4, "text": "Coloque as almôndegas no molho e cozinhe tampado em fogo baixo.", "timerSeconds": 1200}, {"order": 5, "text": "Sirva com manjericão e parmesão, sobre macarrão ou arroz."}]'::jsonb, ARRAY['carne-moida','ovo','farinha-rosca','cebola','alho','molho-tomate']::text[]),
  ('arroz-carreteiro', 'Arroz carreteiro', 'prato-principal', 45, 4, 'media', NULL, '[{"id": "arroz", "name": "Arroz", "text": "2 xícaras de arroz", "optional": false}, {"id": "carne-seca", "name": "Carne-seca", "text": "400 g de carne-seca dessalgada e cozida (ou sobra de churrasco)", "optional": false}, {"id": "linguica", "name": "Linguiça calabresa", "text": "1 linguiça calabresa", "optional": true}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": false}]'::jsonb, '[{"order": 1, "text": "Desfie a carne-seca e doure com a linguiça picada numa panela.", "timerSeconds": 480}, {"order": 2, "text": "Junte a cebola, o alho e o tomate e refogue.", "timerSeconds": 240}, {"order": 3, "text": "Adicione o arroz, misture e cubra com 4 xícaras de água quente.", "timerSeconds": 60}, {"order": 4, "text": "Cozinhe até secar e finalize com bastante cheiro-verde.", "timerSeconds": 1080}]'::jsonb, ARRAY['arroz','carne-seca','cebola','alho','tomate','cheiro-verde']::text[]),
  ('arroz-de-forno', 'Arroz de forno', 'prato-principal', 40, 6, 'facil', NULL, '[{"id": "arroz", "name": "Arroz", "text": "4 xícaras de arroz cozido", "optional": false}, {"id": "presunto", "name": "Presunto", "text": "150 g de presunto em cubos", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "200 g de muçarela ralada", "optional": false}, {"id": "milho", "name": "Milho verde em lata", "text": "1 lata de milho", "optional": false}, {"id": "ervilha", "name": "Ervilha em lata", "text": "1 lata de ervilha", "optional": true}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "1 xícara de molho de tomate", "optional": false}, {"id": "requeijao", "name": "Requeijão", "text": "1/2 copo de requeijão", "optional": true}, {"id": "frango", "name": "Frango", "text": "1 xícara de frango desfiado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o arroz com o presunto, o milho, a ervilha, o frango, o molho e o requeijão."}, {"order": 2, "text": "Coloque numa travessa e cubra com a muçarela."}, {"order": 3, "text": "Leve ao forno a 200 °C até o queijo derreter e dourar.", "timerSeconds": 1200}]'::jsonb, ARRAY['arroz','presunto','queijo','milho','molho-tomate']::text[]),
  ('arroz-frito-com-ovo', 'Arroz frito com ovo', 'prato-principal', 15, 2, 'facil', NULL, '[{"id": "arroz", "name": "Arroz", "text": "2 xícaras de arroz cozido frio", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura em cubinhos", "optional": false}, {"id": "shoyu", "name": "Shoyu", "text": "2 colheres (sopa) de shoyu", "optional": false}, {"id": "ervilha", "name": "Ervilha em lata", "text": "1/2 xícara de ervilha", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cebolinha picada", "optional": true}, {"id": "presunto", "name": "Presunto", "text": "Presunto em cubos", "optional": true}]'::jsonb, '[{"order": 1, "text": "Mexa os ovos numa frigideira grande com óleo, quebrando em pedaços, e reserve.", "timerSeconds": 120}, {"order": 2, "text": "Na mesma frigideira, refogue a cenoura, a ervilha e o presunto em fogo alto.", "timerSeconds": 240}, {"order": 3, "text": "Junte o arroz e o shoyu e salteie até o arroz ficar soltinho e quente.", "timerSeconds": 240}, {"order": 4, "text": "Volte os ovos, misture e finalize com cebolinha."}]'::jsonb, ARRAY['arroz','ovo','cenoura','shoyu']::text[]),
  ('baiao-de-dois', 'Baião de dois', 'prato-principal', 50, 4, 'media', NULL, '[{"id": "arroz", "name": "Arroz", "text": "1 1/2 xícara de arroz", "optional": false}, {"id": "feijao", "name": "Feijão", "text": "2 xícaras de feijão-de-corda (ou carioca) cozido, com caldo", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "150 g de bacon", "optional": false}, {"id": "linguica", "name": "Linguiça calabresa", "text": "1 linguiça calabresa", "optional": true}, {"id": "queijo-minas", "name": "Queijo minas", "text": "150 g de queijo coalho ou minas em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Coentro ou cheiro-verde", "optional": false}]'::jsonb, '[{"order": 1, "text": "Doure o bacon e a linguiça picados.", "timerSeconds": 360}, {"order": 2, "text": "Junte a cebola e o alho, depois o arroz, e refogue.", "timerSeconds": 180}, {"order": 3, "text": "Adicione o feijão com caldo e água quente até cobrir 2 dedos. Cozinhe até o arroz ficar macio.", "timerSeconds": 1200}, {"order": 4, "text": "Misture o queijo e o coentro, tampe e deixe o queijo amolecer.", "timerSeconds": 180}]'::jsonb, ARRAY['arroz','feijao','bacon','queijo-minas','cebola','alho','cheiro-verde']::text[]),
  ('berinjela-a-parmegiana', 'Berinjela à parmegiana', 'prato-principal', 60, 4, 'media', NULL, '[{"id": "berinjela", "name": "Berinjela", "text": "2 berinjelas em rodelas", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos batidos", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1 xícara de farinha de rosca", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "2 xícaras de molho de tomate", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "200 g de muçarela", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão ralado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Salpique sal nas rodelas de berinjela e deixe soltar o amargor. Depois seque com papel.", "timerSeconds": 900}, {"order": 2, "text": "Passe no ovo e na farinha de rosca e asse numa assadeira untada a 200 °C, virando na metade.", "timerSeconds": 1200}, {"order": 3, "text": "Num refratário, alterne camadas de molho, berinjela e queijo."}, {"order": 4, "text": "Gratine a 200 °C.", "timerSeconds": 900}]'::jsonb, ARRAY['berinjela','ovo','farinha-rosca','molho-tomate','queijo']::text[]),
  ('bife-acebolado', 'Bife acebolado', 'prato-principal', 20, 4, 'facil', NULL, '[{"id": "carne-bovina", "name": "Carne bovina (bife ou cubos)", "text": "4 bifes (contrafilé ou alcatra)", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "2 cebolas em rodelas", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "vinagre", "name": "Vinagre", "text": "1 colher (sopa) de vinagre", "optional": true}]'::jsonb, '[{"order": 1, "text": "Tempere os bifes com alho, sal e pimenta."}, {"order": 2, "text": "Frite em frigideira bem quente, sem mexer, até dourar. Vire e repita.", "timerSeconds": 240}, {"order": 3, "text": "Retire os bifes e, na mesma frigideira, doure a cebola com o vinagre e um pouco de água, raspando o fundo.", "timerSeconds": 300}, {"order": 4, "text": "Volte os bifes por cima da cebola e sirva."}]'::jsonb, ARRAY['carne-bovina','cebola','alho']::text[]),
  ('bisteca-acebolada', 'Bisteca de porco acebolada', 'prato-principal', 35, 4, 'facil', NULL, '[{"id": "carne-porco", "name": "Carne de porco (lombo ou bisteca)", "text": "4 bistecas de porco", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1 limão", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho amassados", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "2 cebolas em rodelas", "optional": false}]'::jsonb, '[{"order": 1, "text": "Tempere as bistecas com limão, alho, sal e pimenta.", "timerSeconds": 900}, {"order": 2, "text": "Frite em frigideira com pouco óleo, em fogo médio, até dourar e cozinhar por dentro.", "timerSeconds": 360}, {"order": 3, "text": "Vire e repita do outro lado.", "timerSeconds": 360}, {"order": 4, "text": "Retire e doure a cebola na mesma frigideira. Sirva por cima das bistecas.", "timerSeconds": 300}]'::jsonb, ARRAY['carne-porco','limao','alho','cebola']::text[]),
  ('bobo-de-camarao', 'Bobó de camarão', 'prato-principal', 60, 4, 'media', NULL, '[{"id": "camarao", "name": "Camarão", "text": "500 g de camarão limpo", "optional": false}, {"id": "mandioca", "name": "Mandioca", "text": "500 g de mandioca", "optional": false}, {"id": "leite-coco", "name": "Leite de coco", "text": "1 vidro de leite de coco", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates picados", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1/2 pimentão picado", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Coentro ou cheiro-verde", "optional": false}]'::jsonb, '[{"order": 1, "text": "Cozinhe a mandioca até ficar bem macia e bata no liquidificador com o leite de coco e um pouco da água do cozimento.", "timerSeconds": 1500}, {"order": 2, "text": "Tempere o camarão com sal e alho e refogue rapidamente. Reserve.", "timerSeconds": 180}, {"order": 3, "text": "Na mesma panela, refogue a cebola, o tomate e o pimentão.", "timerSeconds": 300}, {"order": 4, "text": "Junte o creme de mandioca e cozinhe mexendo até encorpar.", "timerSeconds": 300}, {"order": 5, "text": "Volte o camarão, aqueça e finalize com coentro.", "timerSeconds": 120}]'::jsonb, ARRAY['camarao','mandioca','leite-coco','cebola','alho','tomate','cheiro-verde']::text[]),
  ('camarao-alho-e-oleo', 'Camarão alho e óleo', 'prato-principal', 15, 2, 'facil', NULL, '[{"id": "camarao", "name": "Camarão", "text": "400 g de camarão limpo", "optional": false}, {"id": "alho", "name": "Alho", "text": "6 dentes de alho fatiados", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "4 colheres (sopa) de azeite", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1/2 limão", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Salsinha picada", "optional": true}]'::jsonb, '[{"order": 1, "text": "Tempere o camarão com sal e limão."}, {"order": 2, "text": "Doure o alho no azeite em fogo baixo, sem deixar queimar.", "timerSeconds": 120}, {"order": 3, "text": "Aumente o fogo, junte o camarão e salteie até ficar rosado. Não passe do ponto para não endurecer.", "timerSeconds": 180}, {"order": 4, "text": "Finalize com salsinha."}]'::jsonb, ARRAY['camarao','alho','azeite','limao']::text[]),
  ('carne-de-panela', 'Carne de panela', 'prato-principal', 80, 6, 'media', NULL, '[{"id": "carne-bovina", "name": "Carne bovina (bife ou cubos)", "text": "1 kg de acém ou músculo em pedaços grandes", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "2 cebolas", "optional": false}, {"id": "alho", "name": "Alho", "text": "4 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates", "optional": false}, {"id": "batata", "name": "Batata", "text": "3 batatas", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "2 cenouras", "optional": false}, {"id": "louro", "name": "Folha de louro", "text": "2 folhas de louro", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure bem a carne temperada na panela de pressão aberta, em partes.", "timerSeconds": 900}, {"order": 2, "text": "Junte a cebola, o alho, o tomate e o louro e refogue. Cubra com água."}, {"order": 3, "text": "Feche a panela e cozinhe depois que pegar pressão.", "timerSeconds": 2400}, {"order": 4, "text": "Espere a pressão sair, abra, junte a batata e a cenoura e cozinhe com a panela aberta até ficarem macias.", "timerSeconds": 900}]'::jsonb, ARRAY['carne-bovina','cebola','alho','tomate','batata','cenoura']::text[]),
  ('carne-moida-refogada', 'Carne moída refogada', 'prato-principal', 25, 4, 'facil', NULL, '[{"id": "carne-moida", "name": "Carne moída", "text": "500 g de carne moída", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates picados", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure a carne num fio de óleo em fogo alto, soltando os pedaços com a colher.", "timerSeconds": 480}, {"order": 2, "text": "Junte a cebola e o alho e refogue.", "timerSeconds": 180}, {"order": 3, "text": "Adicione o tomate, sal e pimenta e cozinhe em fogo baixo até virar um molhinho.", "timerSeconds": 600}, {"order": 4, "text": "Finalize com cheiro-verde."}]'::jsonb, ARRAY['carne-moida','cebola','alho','tomate']::text[]),
  ('chili-com-feijao', 'Chili de carne com feijão', 'prato-principal', 40, 4, 'facil', NULL, '[{"id": "carne-moida", "name": "Carne moída", "text": "400 g de carne moída", "optional": false}, {"id": "feijao", "name": "Feijão", "text": "2 xícaras de feijão cozido (de preferência vermelho)", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "3 tomates picados (ou 1 lata de pelado)", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1 pimentão picado", "optional": true}, {"id": "cominho", "name": "Cominho", "text": "1 colher (chá) de cominho", "optional": true}, {"id": "paprica", "name": "Páprica", "text": "1 colher (chá) de páprica", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure a carne em fogo alto, soltando bem.", "timerSeconds": 420}, {"order": 2, "text": "Junte a cebola, o alho, o pimentão e os temperos e refogue.", "timerSeconds": 240}, {"order": 3, "text": "Adicione o tomate e o feijão com um pouco do caldo. Cozinhe em fogo baixo até engrossar.", "timerSeconds": 1200}, {"order": 4, "text": "Sirva com arroz ou com pão."}]'::jsonb, ARRAY['carne-moida','feijao','tomate','cebola','alho']::text[]),
  ('coxas-assadas-com-paprica', 'Coxas de frango assadas com páprica', 'prato-principal', 60, 4, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "8 coxas de frango", "optional": false}, {"id": "paprica", "name": "Páprica", "text": "1 colher (sopa) de páprica", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho amassados", "optional": false}, {"id": "mel", "name": "Mel", "text": "1 colher (sopa) de mel", "optional": true}, {"id": "oleo", "name": "Óleo", "text": "2 colheres (sopa) de óleo", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture a páprica, o alho, o mel, o óleo, sal e pimenta e esfregue nas coxas.", "timerSeconds": 900}, {"order": 2, "text": "Arrume numa assadeira com a pele para cima."}, {"order": 3, "text": "Asse a 200 °C, virando uma vez, até a pele ficar bem dourada.", "timerSeconds": 2700}]'::jsonb, ARRAY['frango','paprica','alho']::text[]),
