  ('feijoada-simples', 'Feijoada simples', 'prato-principal', 150, 8, 'dificil', NULL, '[{"id": "feijao", "name": "Feijão", "text": "500 g de feijão-preto", "optional": false}, {"id": "linguica", "name": "Linguiça calabresa", "text": "2 linguiças calabresas", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "200 g de bacon", "optional": false}, {"id": "carne-seca", "name": "Carne-seca", "text": "300 g de carne-seca dessalgada", "optional": true}, {"id": "carne-porco", "name": "Carne de porco (lombo ou bisteca)", "text": "300 g de lombo ou costelinha", "optional": true}, {"id": "cebola", "name": "Cebola", "text": "1 cebola", "optional": false}, {"id": "alho", "name": "Alho", "text": "5 dentes de alho", "optional": false}, {"id": "louro", "name": "Folha de louro", "text": "3 folhas de louro", "optional": false}, {"id": "laranja", "name": "Laranja", "text": "Laranja para servir", "optional": true}]'::jsonb, '[{"order": 1, "text": "Deixe o feijão de molho em água (o ideal é de véspera).", "timerSeconds": 3600}, {"order": 2, "text": "Cozinhe o feijão com o louro e as carnes mais duras (carne-seca e porco) na pressão.", "timerSeconds": 2400}, {"order": 3, "text": "Doure o bacon e a linguiça em rodelas, junte a cebola e o alho e refogue."}, {"order": 4, "text": "Misture o refogado ao feijão e cozinhe em fogo baixo, com a panela aberta, até engrossar.", "timerSeconds": 1800}, {"order": 5, "text": "Sirva com arroz, couve refogada, farofa e laranja."}]'::jsonb, ARRAY['feijao','linguica','bacon','cebola','alho','louro']::text[]),
