  ('frango-com-batata-doce', 'Frango com batata-doce assada', 'prato-principal', 45, 2, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "2 filés de peito de frango", "optional": false}, {"id": "batata-doce", "name": "Batata-doce", "text": "2 batatas-doces em rodelas", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "2 colheres (sopa) de azeite", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "paprica", "name": "Páprica", "text": "Páprica a gosto", "optional": true}, {"id": "brocolis", "name": "Brócolis", "text": "Brócolis no vapor para acompanhar", "optional": true}]'::jsonb, '[{"order": 1, "text": "Espalhe a batata-doce numa assadeira, regue com azeite, sal e páprica."}, {"order": 2, "text": "Asse a 200 °C, virando na metade.", "timerSeconds": 1800}, {"order": 3, "text": "Enquanto isso, tempere e grelhe o frango numa frigideira quente.", "timerSeconds": 600}, {"order": 4, "text": "Sirva o frango com a batata-doce e o brócolis."}]'::jsonb, ARRAY['frango','batata-doce','azeite','alho']::text[]),
  ('frango-com-quiabo', 'Frango com quiabo', 'prato-principal', 60, 4, 'media', NULL, '[{"id": "frango", "name": "Frango", "text": "1 kg de frango em pedaços", "optional": false}, {"id": "quiabo", "name": "Quiabo", "text": "400 g de quiabo em rodelas", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates picados", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1 limão", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Tempere o frango com limão, alho, sal e pimenta e doure numa panela com óleo.", "timerSeconds": 900}, {"order": 2, "text": "Junte a cebola e o tomate e refogue. Cubra com água e cozinhe até o frango ficar macio.", "timerSeconds": 1500}, {"order": 3, "text": "Em outra frigideira, refogue o quiabo em fogo alto, sem tampar, para tirar a baba.", "timerSeconds": 600}, {"order": 4, "text": "Misture o quiabo ao frango, cozinhe mais um pouco e finalize com cheiro-verde.", "timerSeconds": 300}]'::jsonb, ARRAY['frango','quiabo','cebola','alho','tomate','limao']::text[]),
  ('frango-desfiado-refogado', 'Frango desfiado refogado', 'prato-principal', 40, 4, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de peito de frango", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates picados", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe o frango em água com sal até ficar macio.", "timerSeconds": 1500}, {"order": 2, "text": "Escorra, espere amornar e desfie com dois garfos."}, {"order": 3, "text": "Refogue a cebola e o alho, junte o tomate e o frango e cozinhe até secar o caldo.", "timerSeconds": 480}, {"order": 4, "text": "Finalize com cheiro-verde. Serve como prato ou recheio de tortas e sanduíches."}]'::jsonb, ARRAY['frango','cebola','alho','tomate']::text[]),
  ('frango-empanado', 'Frango empanado à milanesa', 'prato-principal', 35, 4, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "4 filés finos de peito de frango", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1/2 limão", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1/2 xícara de farinha de trigo", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos batidos", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1 xícara de farinha de rosca", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Tempere os filés com limão, sal e pimenta.", "timerSeconds": 600}, {"order": 2, "text": "Passe na farinha de trigo, depois no ovo e por último na farinha de rosca, apertando bem."}, {"order": 3, "text": "Frite em óleo quente até dourar, virando na metade.", "timerSeconds": 360}, {"order": 4, "text": "Escorra em papel-toalha e sirva com limão."}]'::jsonb, ARRAY['frango','limao','farinha-trigo','ovo','farinha-rosca']::text[]),
  ('frango-grelhado-com-limao', 'Frango grelhado com limão', 'prato-principal', 25, 2, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "2 filés de peito de frango", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1 limão", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho amassados", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "1 colher (sopa) de azeite", "optional": false}, {"id": "oregano", "name": "Orégano", "text": "Orégano a gosto", "optional": true}]'::jsonb, '[{"order": 1, "text": "Tempere os filés com limão, alho, orégano, sal e pimenta.", "timerSeconds": 900}, {"order": 2, "text": "Aqueça bem uma frigideira com o azeite e coloque os filés sem mexer.", "timerSeconds": 300}, {"order": 3, "text": "Vire e grelhe o outro lado até ficar dourado e cozido por dentro.", "timerSeconds": 300}]'::jsonb, ARRAY['frango','limao','alho','azeite']::text[]),
  ('frango-xadrez', 'Frango xadrez', 'prato-principal', 30, 3, 'media', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de peito de frango em cubos", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1 pimentão (ou 1/2 verde e 1/2 vermelho) em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola em cubos grandes", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "shoyu", "name": "Shoyu", "text": "1/2 xícara de shoyu", "optional": false}, {"id": "amido-milho", "name": "Amido de milho", "text": "1 colher (sopa) de amido de milho", "optional": false}, {"id": "amendoim", "name": "Amendoim", "text": "1/2 xícara de amendoim torrado", "optional": true}, {"id": "oleo", "name": "Óleo", "text": "2 colheres (sopa) de óleo", "optional": false}]'::jsonb, '[{"order": 1, "text": "Tempere o frango com metade do shoyu e o alho.", "timerSeconds": 600}, {"order": 2, "text": "Doure o frango no óleo bem quente, em partes, para não soltar água.", "timerSeconds": 360}, {"order": 3, "text": "Junte a cebola e o pimentão e refogue rapidamente, deixando crocantes.", "timerSeconds": 180}, {"order": 4, "text": "Dissolva o amido no resto do shoyu com 1/2 xícara de água, despeje e mexa até engrossar.", "timerSeconds": 120}, {"order": 5, "text": "Finalize com o amendoim e sirva com arroz."}]'::jsonb, ARRAY['frango','pimentao','cebola','alho','shoyu','amido-milho']::text[]),
  ('frango-a-parmegiana', 'Frango à parmegiana', 'prato-principal', 50, 4, 'media', NULL, '[{"id": "frango", "name": "Frango", "text": "4 filés de peito de frango", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1/2 xícara de farinha de trigo", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos batidos", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1 xícara de farinha de rosca", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "2 xícaras de molho de tomate", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "200 g de muçarela fatiada", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão ralado", "optional": true}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Tempere os filés com sal e pimenta. Passe na farinha de trigo, no ovo e na farinha de rosca."}, {"order": 2, "text": "Frite em óleo quente até dourar dos dois lados.", "timerSeconds": 360}, {"order": 3, "text": "Coloque os filés numa travessa, cubra com o molho, a muçarela e o parmesão."}, {"order": 4, "text": "Leve ao forno a 200 °C até o queijo derreter e gratinar.", "timerSeconds": 900}]'::jsonb, ARRAY['frango','farinha-trigo','ovo','farinha-rosca','molho-tomate','queijo']::text[]),
  ('fricasse-de-frango', 'Fricassê de frango', 'prato-principal', 45, 4, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de frango cozido e desfiado", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "milho", "name": "Milho verde em lata", "text": "1 lata de milho", "optional": false}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "1 caixa de creme de leite", "optional": false}, {"id": "requeijao", "name": "Requeijão", "text": "1/2 copo de requeijão", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "150 g de muçarela", "optional": false}, {"id": "batata-palha", "name": "Batata palha", "text": "Batata palha para cobrir", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola, junte o frango e tempere com sal.", "timerSeconds": 300}, {"order": 2, "text": "Bata o milho com o creme de leite e o requeijão no liquidificador e misture ao frango."}, {"order": 3, "text": "Coloque numa travessa, cubra com a muçarela e leve ao forno a 200 °C.", "timerSeconds": 1200}, {"order": 4, "text": "Na hora de servir, cubra com batata palha."}]'::jsonb, ARRAY['frango','cebola','milho','creme-de-leite','requeijao','queijo']::text[]),
  ('fritada-de-legumes', 'Fritada de legumes', 'prato-principal', 25, 3, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "5 ovos", "optional": false}, {"id": "abobrinha", "name": "Abobrinha", "text": "1 abobrinha ralada", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola picada", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "1/2 xícara de muçarela ou parmesão", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola e a abobrinha numa frigideira que possa ir ao forno.", "timerSeconds": 300}, {"order": 2, "text": "Bata os ovos com sal, o queijo e o cheiro-verde e despeje sobre os legumes com o tomate."}, {"order": 3, "text": "Cozinhe tampado em fogo baixo até firmar as bordas.", "timerSeconds": 480}, {"order": 4, "text": "Termine no forno a 200 °C até dourar por cima, ou vire com a ajuda de um prato.", "timerSeconds": 420}]'::jsonb, ARRAY['ovo','abobrinha','cebola','tomate']::text[]),
  ('galinhada', 'Galinhada', 'prato-principal', 50, 4, 'media', NULL, '[{"id": "frango", "name": "Frango", "text": "800 g de coxas e sobrecoxas em pedaços", "optional": false}, {"id": "arroz", "name": "Arroz", "text": "2 xícaras de arroz", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "acafrao", "name": "Açafrão-da-terra", "text": "1 colher (chá) de açafrão-da-terra", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": true}, {"id": "milho", "name": "Milho verde em lata", "text": "1/2 lata de milho", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Tempere o frango com sal, alho e açafrão e doure bem numa panela grande com óleo.", "timerSeconds": 900}, {"order": 2, "text": "Junte a cebola e o tomate e refogue.", "timerSeconds": 180}, {"order": 3, "text": "Adicione o arroz, mexa para envolver no tempero e cubra com 4 xícaras de água quente."}, {"order": 4, "text": "Cozinhe com a panela semitampada até secar.", "timerSeconds": 1200}, {"order": 5, "text": "Misture o milho e o cheiro-verde e deixe descansar tampado.", "timerSeconds": 300}]'::jsonb, ARRAY['frango','arroz','cebola','alho','acafrao']::text[]),
  ('grao-de-bico-ao-leite-de-coco', 'Grão-de-bico ao leite de coco', 'prato-principal', 30, 4, 'facil', NULL, '[{"id": "grao-de-bico", "name": "Grão-de-bico", "text": "2 xícaras de grão-de-bico cozido", "optional": false}, {"id": "leite-coco", "name": "Leite de coco", "text": "1 vidro de leite de coco", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates picados", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "acafrao", "name": "Açafrão-da-terra", "text": "1 colher (chá) de açafrão-da-terra", "optional": false}, {"id": "gengibre", "name": "Gengibre", "text": "Gengibre ralado", "optional": true}, {"id": "espinafre", "name": "Espinafre", "text": "1 maço de espinafre", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola, o alho, o gengibre e o açafrão.", "timerSeconds": 240}, {"order": 2, "text": "Junte o tomate e cozinhe até desmanchar.", "timerSeconds": 300}, {"order": 3, "text": "Adicione o grão-de-bico e o leite de coco e cozinhe em fogo baixo até encorpar.", "timerSeconds": 600}, {"order": 4, "text": "Se usar, misture o espinafre no final só para murchar. Sirva com arroz."}]'::jsonb, ARRAY['grao-de-bico','leite-coco','tomate','cebola','alho','acafrao']::text[]),
  ('hamburguer-de-grao-de-bico', 'Hambúrguer de grão-de-bico', 'prato-principal', 40, 4, 'media', NULL, '[{"id": "grao-de-bico", "name": "Grão-de-bico", "text": "2 xícaras de grão-de-bico cozido", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola", "optional": false}, {"id": "alho", "name": "Alho", "text": "1 dente de alho", "optional": false}, {"id": "farinha-rosca", "name": "Farinha de rosca", "text": "1/2 xícara de farinha de rosca (ou aveia)", "optional": false}, {"id": "cominho", "name": "Cominho", "text": "1/2 colher (chá) de cominho", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": false}]'::jsonb, '[{"order": 1, "text": "Triture o grão-de-bico com a cebola, o alho, o cheiro-verde, o cominho e sal, deixando alguns pedacinhos."}, {"order": 2, "text": "Misture a farinha de rosca até a massa dar liga e modele 4 discos."}, {"order": 3, "text": "Leve à geladeira para firmar.", "timerSeconds": 900}, {"order": 4, "text": "Doure numa frigideira com um fio de óleo, dos dois lados.", "timerSeconds": 360}]'::jsonb, ARRAY['grao-de-bico','cebola','alho','farinha-rosca','cheiro-verde']::text[]),
  ('lasanha-a-bolonhesa', 'Lasanha à bolonhesa', 'prato-principal', 80, 6, 'media', NULL, '[{"id": "massa-lasanha", "name": "Massa de lasanha", "text": "500 g de massa de lasanha (pré-cozida)", "optional": false}, {"id": "carne-moida", "name": "Carne moída", "text": "500 g de carne moída", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "3 xícaras de molho de tomate", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "300 g de muçarela fatiada", "optional": false}, {"id": "presunto", "name": "Presunto", "text": "200 g de presunto fatiado", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão ralado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure a carne com a cebola, junte o molho e cozinhe para formar uma bolonhesa bem molhada.", "timerSeconds": 1200}, {"order": 2, "text": "Num refratário, faça camadas: molho, massa, presunto, queijo e molho. Repita até acabar, terminando com molho e queijo."}, {"order": 3, "text": "Cubra com papel-alumínio e asse a 200 °C.", "timerSeconds": 1800}, {"order": 4, "text": "Retire o papel, polvilhe parmesão e gratine.", "timerSeconds": 600}, {"order": 5, "text": "Deixe descansar antes de cortar para as camadas firmarem.", "timerSeconds": 600}]'::jsonb, ARRAY['massa-lasanha','carne-moida','molho-tomate','cebola','queijo','presunto']::text[]),
  ('linguica-acebolada', 'Linguiça acebolada', 'prato-principal', 20, 4, 'facil', NULL, '[{"id": "linguica", "name": "Linguiça calabresa", "text": "2 linguiças calabresas em rodelas", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "2 cebolas em rodelas", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1/2 pimentão em tiras", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure a linguiça numa frigideira sem óleo, em fogo médio.", "timerSeconds": 420}, {"order": 2, "text": "Junte a cebola e o pimentão e refogue até murcharem e dourarem levemente.", "timerSeconds": 300}, {"order": 3, "text": "Sirva como petisco ou com arroz e feijão."}]'::jsonb, ARRAY['linguica','cebola']::text[]),
  ('lombo-assado', 'Lombo de porco assado', 'prato-principal', 110, 6, 'media', NULL, '[{"id": "carne-porco", "name": "Carne de porco (lombo ou bisteca)", "text": "1 kg de lombo de porco", "optional": false}, {"id": "alho", "name": "Alho", "text": "5 dentes de alho", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 2 limões", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola", "optional": false}, {"id": "batata", "name": "Batata", "text": "4 batatas", "optional": true}, {"id": "mostarda", "name": "Mostarda", "text": "2 colheres (sopa) de mostarda", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata o alho, a cebola, o limão, a mostarda e sal no liquidificador e cubra o lombo com essa pasta."}, {"order": 2, "text": "Deixe marinando na geladeira (o ideal é de um dia para o outro).", "timerSeconds": 3600}, {"order": 3, "text": "Coloque numa assadeira com as batatas, cubra com papel-alumínio e asse a 200 °C.", "timerSeconds": 2700}, {"order": 4, "text": "Retire o papel e asse regando com o caldo da assadeira até dourar.", "timerSeconds": 1800}]'::jsonb, ARRAY['carne-porco','alho','limao','cebola']::text[]),
  ('macarrao-alho-e-oleo', 'Macarrão alho e óleo', 'prato-principal', 20, 2, 'facil', NULL, '[{"id": "macarrao", "name": "Macarrão", "text": "250 g de espaguete", "optional": false}, {"id": "alho", "name": "Alho", "text": "5 dentes de alho fatiados", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "1/4 de xícara de azeite", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Salsinha picada", "optional": true}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão ralado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe o macarrão em bastante água fervente com sal, até ficar al dente. Guarde 1/2 xícara da água.", "timerSeconds": 540}, {"order": 2, "text": "Enquanto isso, doure o alho no azeite em fogo baixo, sem queimar.", "timerSeconds": 180}, {"order": 3, "text": "Junte o macarrão escorrido e um pouco da água do cozimento e misture bem.", "timerSeconds": 60}, {"order": 4, "text": "Finalize com salsinha e parmesão."}]'::jsonb, ARRAY['macarrao','alho','azeite']::text[]),
  ('macarrao-ao-molho-branco', 'Macarrão ao molho branco', 'prato-principal', 25, 3, 'facil', NULL, '[{"id": "macarrao", "name": "Macarrão", "text": "350 g de macarrão", "optional": false}, {"id": "leite", "name": "Leite", "text": "2 xícaras de leite", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "2 colheres (sopa) de manteiga", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "2 colheres (sopa) de farinha de trigo", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "1/2 xícara de parmesão ralado", "optional": false}, {"id": "noz-moscada", "name": "Noz-moscada", "text": "1 pitada de noz-moscada", "optional": true}, {"id": "presunto", "name": "Presunto", "text": "Presunto em cubos", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe o macarrão em água fervente com sal.", "timerSeconds": 540}, {"order": 2, "text": "Derreta a manteiga, junte a farinha e mexa por 1 minuto.", "timerSeconds": 60}, {"order": 3, "text": "Adicione o leite aos poucos, mexendo sem parar, até engrossar. Tempere com sal e noz-moscada.", "timerSeconds": 300}, {"order": 4, "text": "Misture o parmesão, o presunto e o macarrão escorrido."}]'::jsonb, ARRAY['macarrao','leite','manteiga','farinha-trigo','parmesao']::text[]),
  ('macarrao-com-atum', 'Macarrão com atum', 'prato-principal', 20, 3, 'facil', NULL, '[{"id": "macarrao", "name": "Macarrão", "text": "300 g de macarrão", "optional": false}, {"id": "atum", "name": "Atum em lata", "text": "1 lata de atum", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "1 xícara de molho de tomate", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1/2 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "1 dente de alho", "optional": false}, {"id": "azeitona", "name": "Azeitona", "text": "Azeitonas", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe o macarrão em água fervente com sal.", "timerSeconds": 540}, {"order": 2, "text": "Refogue a cebola e o alho, junte o atum e o molho de tomate.", "timerSeconds": 300}, {"order": 3, "text": "Misture o macarrão escorrido ao molho, com as azeitonas e o cheiro-verde."}]'::jsonb, ARRAY['macarrao','atum','molho-tomate','cebola','alho']::text[]),
  ('macarrao-a-bolonhesa', 'Macarrão à bolonhesa', 'prato-principal', 40, 4, 'facil', NULL, '[{"id": "macarrao", "name": "Macarrão", "text": "500 g de macarrão", "optional": false}, {"id": "carne-moida", "name": "Carne moída", "text": "500 g de carne moída", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "2 xícaras de molho de tomate", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura ralada", "optional": true}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão ralado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure a carne em fogo alto, junte a cebola, o alho e a cenoura e refogue.", "timerSeconds": 600}, {"order": 2, "text": "Adicione o molho de tomate e meia xícara de água. Cozinhe em fogo baixo, tampado.", "timerSeconds": 1200}, {"order": 3, "text": "Enquanto o molho apura, cozinhe o macarrão em água fervente com sal.", "timerSeconds": 540}, {"order": 4, "text": "Escorra, misture ao molho e sirva com parmesão."}]'::jsonb, ARRAY['macarrao','carne-moida','molho-tomate','cebola','alho']::text[]),
  ('macarrao-carbonara', 'Macarrão à carbonara caseiro', 'prato-principal', 25, 2, 'media', NULL, '[{"id": "macarrao", "name": "Macarrão", "text": "250 g de espaguete", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "150 g de bacon em cubos", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos + 1 gema", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "1/2 xícara de parmesão ralado", "optional": false}, {"id": "pimenta-do-reino", "name": "Pimenta-do-reino", "text": "Pimenta-do-reino moída na hora", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata os ovos, a gema, o parmesão e bastante pimenta numa tigela."}, {"order": 2, "text": "Cozinhe o macarrão em água fervente com sal. Guarde 1/2 xícara da água.", "timerSeconds": 540}, {"order": 3, "text": "Doure o bacon numa frigideira até ficar crocante.", "timerSeconds": 360}, {"order": 4, "text": "Desligue o fogo, junte o macarrão ao bacon e despeje a mistura de ovos mexendo rápido, com um pouco da água, até ficar cremoso. Não volte ao fogo para o ovo não talhar."}]'::jsonb, ARRAY['macarrao','bacon','ovo','parmesao']::text[]),
  ('moqueca-de-peixe', 'Moqueca de peixe', 'prato-principal', 45, 4, 'media', NULL, '[{"id": "peixe", "name": "Filé de peixe", "text": "800 g de peixe firme em postas", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1 limão", "optional": false}, {"id": "leite-coco", "name": "Leite de coco", "text": "1 vidro de leite de coco", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "3 tomates em rodelas", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "2 cebolas em rodelas", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1 pimentão em rodelas", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Coentro ou cheiro-verde", "optional": false}]'::jsonb, '[{"order": 1, "text": "Tempere o peixe com limão, alho e sal.", "timerSeconds": 900}, {"order": 2, "text": "Numa panela larga, faça camadas de cebola, tomate e pimentão, coloque o peixe e cubra com mais uma camada de legumes."}, {"order": 3, "text": "Despeje o leite de coco, tampe e cozinhe em fogo médio sem mexer.", "timerSeconds": 900}, {"order": 4, "text": "Finalize com coentro e sirva com arroz e pirão."}]'::jsonb, ARRAY['peixe','limao','leite-coco','tomate','cebola','pimentao','alho','cheiro-verde']::text[]),
  ('nhoque-de-batata', 'Nhoque de batata', 'prato-principal', 70, 4, 'media', NULL, '[{"id": "batata", "name": "Batata", "text": "1 kg de batata", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1 1/2 xícara de farinha de trigo", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "1 ovo", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "2 xícaras de molho de tomate", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "Parmesão ralado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe as batatas com casca até ficarem macias.", "timerSeconds": 1500}, {"order": 2, "text": "Descasque ainda quentes e esprema. Misture a manteiga, o ovo, sal e a farinha aos poucos até a massa parar de grudar."}, {"order": 3, "text": "Faça rolinhos de 2 cm de espessura e corte em pedaços."}, {"order": 4, "text": "Cozinhe em água fervente com sal. Retire com escumadeira assim que subirem.", "timerSeconds": 180}, {"order": 5, "text": "Sirva com o molho quente e parmesão."}]'::jsonb, ARRAY['batata','farinha-trigo','ovo','manteiga','molho-tomate']::text[]),
  ('ovos-no-molho-de-tomate', 'Ovos no molho de tomate', 'prato-principal', 25, 2, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "4 ovos", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "4 tomates picados (ou 1 lata de tomate pelado)", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1/2 pimentão picado", "optional": true}, {"id": "paprica", "name": "Páprica", "text": "1 colher (chá) de páprica", "optional": true}, {"id": "pao", "name": "Pão francês", "text": "Pão para servir", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola, o alho e o pimentão no azeite ou óleo.", "timerSeconds": 240}, {"order": 2, "text": "Junte o tomate, a páprica e sal. Cozinhe até virar um molho grosso.", "timerSeconds": 600}, {"order": 3, "text": "Faça 4 covas no molho e quebre um ovo em cada uma. Tampe e cozinhe até as claras firmarem.", "timerSeconds": 360}, {"order": 4, "text": "Sirva direto da frigideira, com pão."}]'::jsonb, ARRAY['ovo','tomate','cebola','alho']::text[]),
  ('panqueca-de-carne', 'Panqueca de carne moída', 'prato-principal', 50, 4, 'media', NULL, '[{"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1 xícara de farinha de trigo", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 1/2 xícara de leite", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 ovos", "optional": false}, {"id": "carne-moida", "name": "Carne moída", "text": "400 g de carne moída refogada", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "2 xícaras de molho de tomate", "optional": false}, {"id": "queijo", "name": "Queijo muçarela", "text": "Muçarela ou parmesão para cobrir", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata a farinha, o leite, os ovos e uma pitada de sal no liquidificador."}, {"order": 2, "text": "Numa frigideira antiaderente untada, faça discos finos, cozinhando cada lado rapidamente.", "timerSeconds": 90}, {"order": 3, "text": "Recheie cada panqueca com a carne e enrole."}, {"order": 4, "text": "Arrume numa travessa, cubra com molho e queijo e leve ao forno a 200 °C para gratinar.", "timerSeconds": 900}]'::jsonb, ARRAY['farinha-trigo','leite','ovo','carne-moida','molho-tomate','queijo']::text[]),
  ('peixe-ao-forno-com-batatas', 'Peixe ao forno com batatas', 'prato-principal', 50, 4, 'facil', NULL, '[{"id": "peixe", "name": "Filé de peixe", "text": "4 filés de peixe", "optional": false}, {"id": "batata", "name": "Batata", "text": "4 batatas em rodelas finas", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates em rodelas", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola em rodelas", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "4 colheres (sopa) de azeite", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1 limão", "optional": false}, {"id": "azeitona", "name": "Azeitona", "text": "Azeitonas", "optional": true}]'::jsonb, '[{"order": 1, "text": "Tempere o peixe com limão, sal e pimenta.", "timerSeconds": 600}, {"order": 2, "text": "Forre uma assadeira com as batatas, regue com azeite e sal e asse a 200 °C até começarem a amolecer.", "timerSeconds": 900}, {"order": 3, "text": "Coloque o peixe sobre as batatas e cubra com tomate, cebola e azeitonas."}, {"order": 4, "text": "Regue com mais azeite e asse até o peixe ficar opaco e se desfazer em lascas.", "timerSeconds": 1200}]'::jsonb, ARRAY['peixe','batata','tomate','cebola','azeite','limao']::text[]),
  ('picadinho-de-carne', 'Picadinho de carne com legumes', 'prato-principal', 60, 4, 'facil', NULL, '[{"id": "carne-bovina", "name": "Carne bovina (bife ou cubos)", "text": "600 g de carne em cubos pequenos", "optional": false}, {"id": "batata", "name": "Batata", "text": "2 batatas em cubos", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "2 tomates picados", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure a carne temperada em partes, em panela bem quente.", "timerSeconds": 600}, {"order": 2, "text": "Junte a cebola, o alho e o tomate e refogue.", "timerSeconds": 240}, {"order": 3, "text": "Cubra com água quente e cozinhe tampado até a carne amaciar.", "timerSeconds": 1800}, {"order": 4, "text": "Adicione a batata e a cenoura e cozinhe até ficarem macias.", "timerSeconds": 900}, {"order": 5, "text": "Finalize com cheiro-verde e sirva com arroz."}]'::jsonb, ARRAY['carne-bovina','batata','cenoura','cebola','alho','tomate']::text[]),
  ('polenta-cremosa', 'Polenta cremosa com molho', 'prato-principal', 35, 4, 'facil', NULL, '[{"id": "fuba", "name": "Fubá", "text": "1 xícara de fubá", "optional": false}, {"id": "agua", "name": "Água", "text": "4 xícaras de água", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "2 colheres (sopa) de manteiga", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "1/2 xícara de parmesão ralado", "optional": false}, {"id": "molho-tomate", "name": "Molho de tomate", "text": "2 xícaras de molho de tomate (ou carne moída refogada)", "optional": false}]'::jsonb, '[{"order": 1, "text": "Dissolva o fubá em 1 xícara de água fria."}, {"order": 2, "text": "Ferva o resto da água com sal, junte o fubá dissolvido e mexa sem parar em fogo baixo até engrossar e soltar do fundo.", "timerSeconds": 1200}, {"order": 3, "text": "Desligue e misture a manteiga e o parmesão."}, {"order": 4, "text": "Sirva em pratos fundos com o molho quente por cima."}]'::jsonb, ARRAY['fuba','manteiga','parmesao','molho-tomate']::text[]),
  ('risoto-de-frango', 'Risoto de frango', 'prato-principal', 40, 3, 'media', NULL, '[{"id": "arroz", "name": "Arroz", "text": "1 1/2 xícara de arroz (arbóreo, se tiver)", "optional": false}, {"id": "frango", "name": "Frango", "text": "300 g de frango cozido e desfiado", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "2 colheres (sopa) de manteiga", "optional": false}, {"id": "parmesao", "name": "Queijo parmesão", "text": "1/2 xícara de parmesão ralado", "optional": false}, {"id": "agua", "name": "Água", "text": "1 litro de água quente (ou caldo do frango)", "optional": false}, {"id": "ervilha", "name": "Ervilha em lata", "text": "1/2 xícara de ervilha", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola em metade da manteiga, junte o arroz e mexa por 1 minuto.", "timerSeconds": 60}, {"order": 2, "text": "Vá adicionando a água quente uma concha por vez, mexendo sempre e esperando secar antes da próxima.", "timerSeconds": 1080}, {"order": 3, "text": "Quando o arroz estiver quase macio, junte o frango e a ervilha.", "timerSeconds": 120}, {"order": 4, "text": "Desligue, misture o resto da manteiga e o parmesão até ficar cremoso."}]'::jsonb, ARRAY['arroz','frango','cebola','manteiga','parmesao']::text[]),
