  ('maionese-de-batata', 'Salada de maionese com batata', 'salada', 40, 6, 'facil', NULL, '[{"id": "batata", "name": "Batata", "text": "1 kg de batata em cubos", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "2 cenouras em cubos", "optional": false}, {"id": "maionese", "name": "Maionese", "text": "1 xícara de maionese", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "3 ovos cozidos", "optional": true}, {"id": "milho", "name": "Milho verde em lata", "text": "1/2 lata de milho", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe a batata e a cenoura em água com sal, sem deixar desmanchar.", "timerSeconds": 720}, {"order": 2, "text": "Escorra e espere esfriar completamente.", "timerSeconds": 1200}, {"order": 3, "text": "Misture com a maionese, os ovos picados, o milho e o cheiro-verde. Acerte o sal."}, {"order": 4, "text": "Sirva gelada."}]'::jsonb, ARRAY['batata','cenoura','maionese']::text[]),
  ('salada-de-repolho', 'Salada de repolho com cenoura', 'salada', 15, 4, 'facil', NULL, '[{"id": "repolho", "name": "Repolho", "text": "1/4 de repolho fatiado bem fino", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura ralada", "optional": false}, {"id": "maionese", "name": "Maionese", "text": "3 colheres (sopa) de maionese", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 1/2 limão", "optional": false}, {"id": "maca", "name": "Maçã", "text": "1/2 maçã em tiras", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o repolho, a cenoura e a maçã."}, {"order": 2, "text": "Misture a maionese com o limão e uma pitada de sal e açúcar."}, {"order": 3, "text": "Junte o molho à salada e deixe na geladeira antes de servir.", "timerSeconds": 600}]'::jsonb, ARRAY['repolho','cenoura','maionese','limao']::text[]),
  ('salpicao-de-frango', 'Salpicão de frango', 'salada', 30, 6, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de frango cozido e desfiado", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "2 cenouras raladas", "optional": false}, {"id": "milho", "name": "Milho verde em lata", "text": "1 lata de milho", "optional": false}, {"id": "ervilha", "name": "Ervilha em lata", "text": "1 lata de ervilha", "optional": true}, {"id": "maionese", "name": "Maionese", "text": "1 xícara de maionese", "optional": false}, {"id": "maca", "name": "Maçã", "text": "1 maçã em cubos", "optional": true}, {"id": "batata-palha", "name": "Batata palha", "text": "Batata palha para cobrir", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture o frango, a cenoura, o milho, a ervilha e a maçã."}, {"order": 2, "text": "Junte a maionese, acerte o sal e misture bem."}, {"order": 3, "text": "Leve à geladeira.", "timerSeconds": 1200}, {"order": 4, "text": "Cubra com batata palha só na hora de servir, para não murchar."}]'::jsonb, ARRAY['frango','cenoura','milho','maionese','batata-palha']::text[]),
  ('vinagrete', 'Vinagrete', 'salada', 10, 6, 'facil', NULL, '[{"id": "tomate", "name": "Tomate", "text": "3 tomates em cubinhos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola em cubinhos", "optional": false}, {"id": "pimentao", "name": "Pimentão", "text": "1/2 pimentão em cubinhos", "optional": true}, {"id": "vinagre", "name": "Vinagre", "text": "3 colheres (sopa) de vinagre", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "3 colheres (sopa) de azeite (ou óleo)", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde picado", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture o tomate, a cebola, o pimentão e o cheiro-verde."}, {"order": 2, "text": "Tempere com vinagre, azeite e sal."}, {"order": 3, "text": "Deixe na geladeira para pegar gosto antes de servir.", "timerSeconds": 900}]'::jsonb, ARRAY['tomate','cebola','vinagre','azeite','cheiro-verde']::text[]),
  ('arroz-doce', 'Arroz-doce', 'sobremesa', 45, 6, 'facil', NULL, '[{"id": "arroz", "name": "Arroz", "text": "1 xícara de arroz", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 litro de leite", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela em pau e em pó", "optional": false}, {"id": "agua", "name": "Água", "text": "2 xícaras de água", "optional": false}]'::jsonb, '[{"order": 1, "text": "Cozinhe o arroz na água com a canela em pau até a água secar.", "timerSeconds": 900}, {"order": 2, "text": "Junte o leite e cozinhe em fogo baixo, mexendo de vez em quando, até o arroz ficar bem macio.", "timerSeconds": 1200}, {"order": 3, "text": "Adicione o leite condensado e cozinhe até ficar cremoso.", "timerSeconds": 300}, {"order": 4, "text": "Sirva quente ou gelado, polvilhado com canela."}]'::jsonb, ARRAY['arroz','leite','leite-condensado','canela']::text[]),
  ('banana-caramelizada', 'Banana caramelizada com canela', 'sobremesa', 10, 2, 'facil', NULL, '[{"id": "banana", "name": "Banana", "text": "2 bananas cortadas ao meio no comprido", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "2 colheres (sopa) de açúcar", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela a gosto", "optional": false}]'::jsonb, '[{"order": 1, "text": "Derreta a manteiga com o açúcar numa frigideira em fogo médio."}, {"order": 2, "text": "Coloque as bananas com o lado cortado para baixo e deixe caramelizar.", "timerSeconds": 120}, {"order": 3, "text": "Vire, polvilhe canela e deixe mais um pouco.", "timerSeconds": 90}, {"order": 4, "text": "Sirva puras ou com sorvete."}]'::jsonb, ARRAY['banana','manteiga','canela']::text[]),
  ('beijinho', 'Beijinho', 'sobremesa', 30, 20, 'facil', NULL, '[{"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "coco-ralado", "name": "Coco ralado", "text": "1/2 xícara de coco ralado, mais um pouco para enrolar", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture o leite condensado, o coco e a manteiga numa panela."}, {"order": 2, "text": "Cozinhe em fogo baixo, mexendo sempre, até desgrudar do fundo.", "timerSeconds": 600}, {"order": 3, "text": "Espere esfriar num prato untado.", "timerSeconds": 1200}, {"order": 4, "text": "Enrole bolinhas e passe no coco ralado."}]'::jsonb, ARRAY['leite-condensado','coco-ralado','manteiga']::text[]),
  ('bolo-de-banana', 'Bolo de banana com canela', 'sobremesa', 60, 10, 'facil', NULL, '[{"id": "banana", "name": "Banana", "text": "4 bananas maduras", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1 xícara de açúcar", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "1/2 xícara de óleo", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1 1/2 xícara de farinha de trigo (ou metade aveia)", "optional": false}, {"id": "fermento", "name": "Fermento químico", "text": "1 colher (sopa) de fermento químico", "optional": false}, {"id": "canela", "name": "Canela", "text": "1 colher (chá) de canela", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata 3 bananas, os ovos, o açúcar e o óleo no liquidificador."}, {"order": 2, "text": "Misture a farinha, a canela e por último o fermento."}, {"order": 3, "text": "Coloque numa forma untada e cubra com a banana restante em rodelas e um pouco de açúcar com canela."}, {"order": 4, "text": "Asse a 180 °C até o palito sair limpo.", "timerSeconds": 2400}]'::jsonb, ARRAY['banana','ovo','farinha-trigo','fermento','canela']::text[]),
  ('bolo-de-caneca', 'Bolo de caneca de chocolate', 'sobremesa', 5, 1, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "1 ovo", "optional": false}, {"id": "leite", "name": "Leite", "text": "3 colheres (sopa) de leite", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "2 colheres (sopa) de óleo", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "3 colheres (sopa) de açúcar", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "2 colheres (sopa) de chocolate em pó", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "4 colheres (sopa) de farinha de trigo", "optional": false}, {"id": "fermento", "name": "Fermento químico", "text": "1/2 colher (chá) de fermento químico", "optional": false}]'::jsonb, '[{"order": 1, "text": "Numa caneca grande, bata o ovo com um garfo e junte o leite, o óleo e o açúcar."}, {"order": 2, "text": "Misture o chocolate e a farinha e, por último, o fermento."}, {"order": 3, "text": "Leve ao micro-ondas em potência alta.", "timerSeconds": 120}, {"order": 4, "text": "Espere 1 minuto antes de comer, porque sai muito quente.", "timerSeconds": 60}]'::jsonb, ARRAY['ovo','leite','chocolate-po','farinha-trigo','fermento']::text[]),
  ('bolo-de-cenoura', 'Bolo de cenoura com cobertura de chocolate', 'sobremesa', 60, 12, 'facil', NULL, '[{"id": "cenoura", "name": "Cenoura", "text": "3 cenouras médias", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "3/4 de xícara de óleo", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "2 xícaras de açúcar", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "2 1/2 xícaras de farinha de trigo", "optional": false}, {"id": "fermento", "name": "Fermento químico", "text": "1 colher (sopa) de fermento químico", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "4 colheres (sopa) de chocolate em pó (cobertura)", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga (cobertura)", "optional": false}, {"id": "leite", "name": "Leite", "text": "3 colheres (sopa) de leite (cobertura)", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata as cenouras picadas, os ovos e o óleo no liquidificador. Junte 1 1/2 xícara do açúcar e bata mais."}, {"order": 2, "text": "Passe para uma tigela, misture a farinha e por último o fermento."}, {"order": 3, "text": "Asse numa forma untada a 180 °C até o palito sair limpo.", "timerSeconds": 2400}, {"order": 4, "text": "Para a cobertura, leve ao fogo o chocolate, o resto do açúcar, a manteiga e o leite, mexendo até engrossar um pouco. Espalhe sobre o bolo.", "timerSeconds": 300}]'::jsonb, ARRAY['cenoura','ovo','farinha-trigo','fermento','chocolate-po','manteiga','leite']::text[]),
  ('bolo-de-chocolate', 'Bolo de chocolate simples', 'sobremesa', 55, 12, 'facil', NULL, '[{"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1 1/2 xícara de açúcar", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "1/2 xícara de óleo", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 xícara de leite", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "1 xícara de chocolate em pó", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "2 xícaras de farinha de trigo", "optional": false}, {"id": "fermento", "name": "Fermento químico", "text": "1 colher (sopa) de fermento químico", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata os ovos com o açúcar até clarear. Junte o óleo e o leite."}, {"order": 2, "text": "Misture o chocolate e a farinha peneirados, e por último o fermento."}, {"order": 3, "text": "Asse numa forma untada a 180 °C até o palito sair limpo.", "timerSeconds": 2100}]'::jsonb, ARRAY['ovo','leite','chocolate-po','farinha-trigo','fermento']::text[]),
  ('bolo-de-fuba', 'Bolo de fubá', 'sobremesa', 55, 12, 'facil', NULL, '[{"id": "fuba", "name": "Fubá", "text": "2 xícaras de fubá", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "1 xícara de farinha de trigo", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "2 xícaras de açúcar", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 1/2 xícara de leite", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "1/2 xícara de óleo", "optional": false}, {"id": "fermento", "name": "Fermento químico", "text": "1 colher (sopa) de fermento químico", "optional": false}, {"id": "queijo-minas", "name": "Queijo minas", "text": "1/2 xícara de queijo ralado", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata os ovos, o leite, o óleo e o açúcar no liquidificador."}, {"order": 2, "text": "Junte o fubá e a farinha e bata até ficar liso. Misture o queijo e o fermento com uma colher."}, {"order": 3, "text": "Asse numa forma untada e enfarinhada a 180 °C até dourar.", "timerSeconds": 2400}]'::jsonb, ARRAY['fuba','farinha-trigo','ovo','leite','fermento']::text[]),
  ('brigadeiro', 'Brigadeiro', 'sobremesa', 30, 20, 'facil', NULL, '[{"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "2 colheres (sopa) de chocolate em pó", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "1 colher (sopa) de manteiga", "optional": false}, {"id": "chocolate", "name": "Chocolate em barra", "text": "Chocolate granulado para enrolar", "optional": true}]'::jsonb, '[{"order": 1, "text": "Misture o leite condensado, o chocolate e a manteiga numa panela."}, {"order": 2, "text": "Cozinhe em fogo baixo, mexendo sem parar, até a massa desgrudar do fundo da panela.", "timerSeconds": 600}, {"order": 3, "text": "Passe para um prato untado e espere esfriar.", "timerSeconds": 1200}, {"order": 4, "text": "Unte as mãos, enrole bolinhas e passe no granulado."}]'::jsonb, ARRAY['leite-condensado','chocolate-po','manteiga']::text[]),
  ('brownie', 'Brownie', 'sobremesa', 45, 12, 'media', NULL, '[{"id": "chocolate", "name": "Chocolate em barra", "text": "200 g de chocolate meio amargo", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "150 g de manteiga", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1 xícara de açúcar", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "farinha-trigo", "name": "Farinha de trigo", "text": "3/4 de xícara de farinha de trigo", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "2 colheres (sopa) de chocolate em pó", "optional": true}]'::jsonb, '[{"order": 1, "text": "Derreta o chocolate com a manteiga em banho-maria ou no micro-ondas, de 30 em 30 segundos."}, {"order": 2, "text": "Bata os ovos com o açúcar só até misturar e junte o chocolate derretido."}, {"order": 3, "text": "Misture a farinha e o chocolate em pó delicadamente, sem bater."}, {"order": 4, "text": "Asse numa forma forrada com papel-manteiga a 180 °C. O meio deve ficar úmido.", "timerSeconds": 1500}, {"order": 5, "text": "Espere esfriar antes de cortar.", "timerSeconds": 1200}]'::jsonb, ARRAY['chocolate','manteiga','ovo','farinha-trigo']::text[]),
  ('cocada', 'Cocada cremosa', 'sobremesa', 30, 10, 'facil', NULL, '[{"id": "coco-ralado", "name": "Coco ralado", "text": "200 g de coco ralado", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "leite", "name": "Leite", "text": "1/2 xícara de leite", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1/2 xícara de açúcar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture todos os ingredientes numa panela."}, {"order": 2, "text": "Cozinhe em fogo baixo, mexendo sempre, até começar a soltar do fundo, mas ainda cremosa.", "timerSeconds": 900}, {"order": 3, "text": "Coloque às colheradas num tabuleiro untado e espere esfriar.", "timerSeconds": 1800}]'::jsonb, ARRAY['coco-ralado','leite-condensado','leite']::text[]),
  ('creme-de-morango', 'Creme de morango', 'sobremesa', 15, 6, 'facil', NULL, '[{"id": "morango", "name": "Morango", "text": "2 caixinhas de morango", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "1 caixa de creme de leite", "optional": false}]'::jsonb, '[{"order": 1, "text": "Lave os morangos, separe alguns para decorar e bata o resto no liquidificador com o leite condensado e o creme de leite.", "timerSeconds": 60}, {"order": 2, "text": "Distribua em taças e decore com os morangos reservados."}, {"order": 3, "text": "Leve à geladeira.", "timerSeconds": 3600}]'::jsonb, ARRAY['morango','leite-condensado','creme-de-leite']::text[]),
  ('mousse-de-maracuja', 'Mousse de maracujá', 'sobremesa', 15, 6, 'facil', NULL, '[{"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "1 caixa de creme de leite", "optional": false}, {"id": "maracuja", "name": "Maracujá", "text": "Polpa de 3 maracujás (ou 1/2 xícara de suco concentrado)", "optional": false}]'::jsonb, '[{"order": 1, "text": "Bata o leite condensado, o creme de leite e o suco de maracujá coado no liquidificador.", "timerSeconds": 180}, {"order": 2, "text": "Despeje em taças e decore com sementes de maracujá."}, {"order": 3, "text": "Leve à geladeira até firmar.", "timerSeconds": 7200}]'::jsonb, ARRAY['leite-condensado','creme-de-leite','maracuja']::text[]),
  ('pave-de-chocolate', 'Pavê de chocolate', 'sobremesa', 40, 8, 'facil', NULL, '[{"id": "biscoito-maisena", "name": "Biscoito maisena", "text": "1 pacote de biscoito maisena", "optional": false}, {"id": "leite", "name": "Leite", "text": "2 xícaras de leite, mais um pouco para molhar os biscoitos", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "amido-milho", "name": "Amido de milho", "text": "2 colheres (sopa) de amido de milho", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "2 gemas", "optional": false}, {"id": "chocolate-po", "name": "Chocolate em pó", "text": "3 colheres (sopa) de chocolate em pó", "optional": false}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "1 caixa de creme de leite", "optional": false}]'::jsonb, '[{"order": 1, "text": "Leve ao fogo o leite, o leite condensado, o amido e as gemas, mexendo até engrossar. Separe metade.", "timerSeconds": 480}, {"order": 2, "text": "Na outra metade, misture o chocolate em pó. Junte metade do creme de leite em cada creme."}, {"order": 3, "text": "Num refratário, alterne camadas de biscoito molhado no leite, creme branco e creme de chocolate."}, {"order": 4, "text": "Leve à geladeira.", "timerSeconds": 10800}]'::jsonb, ARRAY['biscoito-maisena','leite','leite-condensado','amido-milho','ovo','chocolate-po','creme-de-leite']::text[]),
  ('pudim-de-leite-condensado', 'Pudim de leite condensado', 'sobremesa', 100, 8, 'media', NULL, '[{"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "leite", "name": "Leite", "text": "A mesma medida da lata de leite", "optional": false}, {"id": "ovo", "name": "Ovo", "text": "3 ovos", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "1 xícara de açúcar para a calda", "optional": false}]'::jsonb, '[{"order": 1, "text": "Derreta o açúcar numa forma de pudim direto no fogo até virar caramelo. Espalhe pelas laterais com cuidado.", "timerSeconds": 300}, {"order": 2, "text": "Bata o leite condensado, o leite e os ovos no liquidificador e despeje na forma."}, {"order": 3, "text": "Cubra com papel-alumínio e asse em banho-maria a 180 °C.", "timerSeconds": 3600}, {"order": 4, "text": "Espere esfriar e leve à geladeira antes de desenformar.", "timerSeconds": 3600}]'::jsonb, ARRAY['leite-condensado','leite','ovo']::text[]),
  ('rabanada', 'Rabanada', 'sobremesa', 25, 4, 'facil', NULL, '[{"id": "pao", "name": "Pão francês", "text": "4 pães franceses amanhecidos em fatias grossas", "optional": false}, {"id": "leite", "name": "Leite", "text": "1 1/2 xícara de leite", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1/2 lata de leite condensado", "optional": true}, {"id": "ovo", "name": "Ovo", "text": "2 ovos batidos", "optional": false}, {"id": "acucar", "name": "Açúcar", "text": "Açúcar para empanar", "optional": false}, {"id": "canela", "name": "Canela", "text": "Canela para empanar", "optional": false}, {"id": "oleo", "name": "Óleo", "text": "Óleo para fritar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture o leite com o leite condensado. Passe as fatias rapidamente na mistura e depois no ovo."}, {"order": 2, "text": "Frite em óleo quente até dourar dos dois lados.", "timerSeconds": 180}, {"order": 3, "text": "Escorra e passe na mistura de açúcar com canela."}]'::jsonb, ARRAY['pao','leite','ovo','canela']::text[]),
  ('salada-de-frutas', 'Salada de frutas', 'sobremesa', 15, 4, 'facil', NULL, '[{"id": "banana", "name": "Banana", "text": "2 bananas", "optional": false}, {"id": "maca", "name": "Maçã", "text": "1 maçã", "optional": false}, {"id": "mamao", "name": "Mamão", "text": "1/2 mamão papaia", "optional": false}, {"id": "laranja", "name": "Laranja", "text": "Suco de 2 laranjas", "optional": false}, {"id": "morango", "name": "Morango", "text": "1 caixinha de morangos", "optional": true}, {"id": "leite-condensado", "name": "Leite condensado", "text": "Leite condensado para servir", "optional": true}]'::jsonb, '[{"order": 1, "text": "Corte todas as frutas em cubos pequenos."}, {"order": 2, "text": "Misture numa tigela e regue com o suco de laranja, que evita que escureçam."}, {"order": 3, "text": "Leve à geladeira e sirva gelada, com leite condensado por cima se quiser.", "timerSeconds": 900}]'::jsonb, ARRAY['banana','maca','mamao','laranja']::text[]),
  ('torta-de-limao', 'Torta de limão', 'sobremesa', 50, 8, 'media', NULL, '[{"id": "biscoito-maisena", "name": "Biscoito maisena", "text": "200 g de biscoito maisena triturado", "optional": false}, {"id": "manteiga", "name": "Manteiga", "text": "100 g de manteiga derretida", "optional": false}, {"id": "leite-condensado", "name": "Leite condensado", "text": "1 lata de leite condensado", "optional": false}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "1 caixa de creme de leite", "optional": false}, {"id": "limao", "name": "Limão", "text": "Suco de 4 limões e raspas para decorar", "optional": false}]'::jsonb, '[{"order": 1, "text": "Misture o biscoito com a manteiga e forre o fundo e as laterais de uma forma de fundo removível."}, {"order": 2, "text": "Asse a base a 180 °C.", "timerSeconds": 600}, {"order": 3, "text": "Bata o leite condensado, o creme de leite e o suco de limão até engrossar. Despeje sobre a base fria."}, {"order": 4, "text": "Leve à geladeira até firmar e decore com raspas de limão.", "timerSeconds": 7200}]'::jsonb, ARRAY['biscoito-maisena','manteiga','leite-condensado','creme-de-leite','limao']::text[]),
  ('caldo-verde', 'Caldo verde', 'sopa', 45, 4, 'facil', NULL, '[{"id": "batata", "name": "Batata", "text": "5 batatas", "optional": false}, {"id": "couve", "name": "Couve", "text": "1 maço de couve cortada bem fina", "optional": false}, {"id": "linguica", "name": "Linguiça calabresa", "text": "1 linguiça calabresa em rodelas", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola", "optional": false}, {"id": "alho", "name": "Alho", "text": "3 dentes de alho", "optional": false}, {"id": "azeite", "name": "Azeite", "text": "Azeite para finalizar", "optional": true}]'::jsonb, '[{"order": 1, "text": "Cozinhe as batatas com a cebola e o alho em 1,5 litro de água com sal até desmancharem.", "timerSeconds": 1200}, {"order": 2, "text": "Bata tudo no liquidificador (com cuidado, está quente) e volte para a panela."}, {"order": 3, "text": "Doure a linguiça numa frigideira e junte ao creme.", "timerSeconds": 360}, {"order": 4, "text": "Acrescente a couve, ferva só para murchar e finalize com azeite.", "timerSeconds": 180}]'::jsonb, ARRAY['batata','couve','linguica','cebola','alho']::text[]),
  ('canja-de-galinha', 'Canja de galinha', 'sopa', 50, 4, 'facil', NULL, '[{"id": "frango", "name": "Frango", "text": "500 g de peito de frango", "optional": false}, {"id": "arroz", "name": "Arroz", "text": "1/2 xícara de arroz", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura em cubos", "optional": false}, {"id": "batata", "name": "Batata", "text": "1 batata em cubos", "optional": true}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": false}]'::jsonb, '[{"order": 1, "text": "Cozinhe o frango em 2 litros de água com sal, cebola e alho.", "timerSeconds": 1500}, {"order": 2, "text": "Retire o frango, desfie e volte para o caldo."}, {"order": 3, "text": "Junte o arroz, a cenoura e a batata e cozinhe até o arroz ficar bem macio.", "timerSeconds": 1200}, {"order": 4, "text": "Finalize com cheiro-verde."}]'::jsonb, ARRAY['frango','arroz','cenoura','cebola','alho','cheiro-verde']::text[]),
  ('creme-de-abobora', 'Creme de abóbora', 'sopa', 35, 4, 'facil', NULL, '[{"id": "abobora", "name": "Abóbora", "text": "800 g de abóbora em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "gengibre", "name": "Gengibre", "text": "1 colher (chá) de gengibre ralado", "optional": true}, {"id": "creme-de-leite", "name": "Creme de leite", "text": "1/2 caixa de creme de leite", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola, o alho e o gengibre.", "timerSeconds": 180}, {"order": 2, "text": "Junte a abóbora, cubra com água e sal e cozinhe até desmanchar.", "timerSeconds": 1200}, {"order": 3, "text": "Bata no liquidificador até ficar liso."}, {"order": 4, "text": "Volte para a panela, misture o creme de leite e aqueça sem ferver.", "timerSeconds": 120}]'::jsonb, ARRAY['abobora','cebola','alho']::text[]),
  ('sopa-de-feijao', 'Sopa de feijão com macarrão', 'sopa', 30, 4, 'facil', NULL, '[{"id": "feijao", "name": "Feijão", "text": "3 xícaras de feijão cozido com caldo", "optional": false}, {"id": "macarrao", "name": "Macarrão", "text": "1 xícara de macarrão pequeno (ave-maria ou argolinha)", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "100 g de bacon", "optional": true}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Bata o feijão com o caldo no liquidificador."}, {"order": 2, "text": "Doure o bacon, junte a cebola e o alho.", "timerSeconds": 300}, {"order": 3, "text": "Adicione o feijão batido e 2 xícaras de água. Quando ferver, junte o macarrão.", "timerSeconds": 600}, {"order": 4, "text": "Cozinhe até o macarrão ficar macio e finalize com cheiro-verde."}]'::jsonb, ARRAY['feijao','macarrao','cebola','alho']::text[]),
  ('sopa-de-legumes', 'Sopa de legumes', 'sopa', 40, 4, 'facil', NULL, '[{"id": "batata", "name": "Batata", "text": "2 batatas em cubos", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "2 cenouras em cubos", "optional": false}, {"id": "abobrinha", "name": "Abobrinha", "text": "1 abobrinha em cubos", "optional": false}, {"id": "chuchu", "name": "Chuchu", "text": "1 chuchu em cubos", "optional": true}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": false}, {"id": "macarrao", "name": "Macarrão", "text": "1/2 xícara de macarrão pequeno", "optional": true}, {"id": "cheiro-verde", "name": "Cheiro-verde", "text": "Cheiro-verde", "optional": true}]'::jsonb, '[{"order": 1, "text": "Refogue a cebola, o alho e o tomate.", "timerSeconds": 240}, {"order": 2, "text": "Junte a batata, a cenoura e o chuchu, cubra com 1,5 litro de água quente e sal.", "timerSeconds": 900}, {"order": 3, "text": "Adicione a abobrinha e o macarrão e cozinhe até tudo ficar macio.", "timerSeconds": 600}, {"order": 4, "text": "Finalize com cheiro-verde."}]'::jsonb, ARRAY['batata','cenoura','abobrinha','cebola','alho','tomate']::text[]),
  ('sopa-de-lentilha', 'Sopa de lentilha', 'sopa', 45, 4, 'facil', NULL, '[{"id": "lentilha", "name": "Lentilha", "text": "1 1/2 xícara de lentilha", "optional": false}, {"id": "cenoura", "name": "Cenoura", "text": "1 cenoura em cubos", "optional": false}, {"id": "cebola", "name": "Cebola", "text": "1 cebola picada", "optional": false}, {"id": "alho", "name": "Alho", "text": "2 dentes de alho", "optional": false}, {"id": "tomate", "name": "Tomate", "text": "1 tomate picado", "optional": false}, {"id": "bacon", "name": "Bacon", "text": "100 g de bacon ou linguiça", "optional": true}, {"id": "cominho", "name": "Cominho", "text": "1/2 colher (chá) de cominho", "optional": true}, {"id": "louro", "name": "Folha de louro", "text": "1 folha de louro", "optional": true}]'::jsonb, '[{"order": 1, "text": "Doure o bacon, junte a cebola, o alho e o tomate e refogue.", "timerSeconds": 360}, {"order": 2, "text": "Adicione a lentilha lavada, a cenoura, o louro, o cominho e 1,5 litro de água.", "timerSeconds": 60}, {"order": 3, "text": "Cozinhe em fogo médio até a lentilha ficar bem macia.", "timerSeconds": 1800}, {"order": 4, "text": "Acerte o sal. Se quiser mais cremosa, bata metade no liquidificador."}]'::jsonb, ARRAY['lentilha','cenoura','cebola','alho','tomate']::text[]);
